(window.JCPA_DATA=window.JCPA_DATA||{})["sales"]={"id":"sales","name":"قانون ضريبة المبيعات","full":"قانون الضريبة العامة على المبيعات رقم (6) لسنة 1994 وتعديلاته","icon":"🛒","articles":[{"n":"1","chapter":"","notes":[],"source":"يسمى هذا القانون (قانون الضريبة العامة على المبيعات لسنة ١٩٩٤) ويعمل به من تاريخ نشره في الجريدة الرسمية.","title":"اسم القانون وبدء العمل به","memo":"⭐ قانون الضريبة العامة على المبيعات لسنة ١٩٩٤\n⭐ يعمل به من تاريخ نشره في الجريدة الرسمية","qs":[{"q":"يعمل بقانون الضريبة العامة على المبيعات لسنة ١٩٩٤ اعتباراً من:","o":["تاريخ نشره في الجريدة الرسمية","تاريخ إقراره من مجلس الأمة","مرور ثلاثين يوماً على نشره في الجريدة الرسمية","بداية السنة المالية التالية لنشره"],"a":0}]},{"n":"2","chapter":"","notes":[],"source":"أ- يكون للكلمات والعبارات التالية حيثما وردت في هذا القانون المعاني المخصصة لها أدناه ما لم تدل القرينة على غير ذلك:\nالوزير:وزير المالية.\nالدائرة:دائرة ضريبة الدخل والمبيعات.\nالمدير:مدير عام الدائرة.\nالضريبة العامة:ضريبة المبيعات المفروضة على استيراد أو بيع أي سلعة أو خدمة وفقا لأحكام الفقرة (أ) من المادة (٦) من هذا القانون.\nالضريبة الخاصة:ضريبة المبيعات المفروضة بنسب خاصة أو بمقادير محددة على استيراد أنواع معينة من السلع والخدمات أو بيعها وفقا لأحكام الفقرة (ب) من المادة (٦) من هذا القانون.\nالضريبة:الضريبة العامة أو الضريبة الخاصة حسب مقتضى الحال.\nالشخص:الشخص الطبيعي أو الشخص الاعتباري.\nالشخص غير المقيم:الشخص الطبيعي الأردني أو الأجنبي الذي أقام خارج المملكة مدة تزيد على مائة وثلاثة وثمانين يوماً خلال الاثني عشر شهراً السابقة لتاريخ مغادرته المملكة.\nالمسجل:الشخص الذي تم تسجيله لدى الدائرة وفق أحكام هذا القانون سواء كان تسجيله إلزامياً أو اختيارياً.\nالمكلف:أي شخص يستورد أو يبيع سلعة أو خدمة خاضعة للضريبة أو كلتيهما معاً وفق أحكام هذا القانون وتم تسجيله أو كان ملزما بالتسجيل لدى الدائرة ويعتبر المستورد مكلفاً وإن كان الاستيراد لأغراضه الخاصة.\nالسلعة:كل مادة طبيعية أو منتج حيواني أو زراعي أو صناعي بما في ذلك الطاقة الكهربائية.\nالخدمة:كل عمل يقوم به الشخص لقاء بدل بما في ذلك تقديم منفعة إلى الغير ولا يشمل هذا العمل تزويد سلعة.\nالسلع المعفاة:السلع والخدمات المدرجة في الجدول رقم (٣) الملحق بهذا القانون أو المعفاة بموجب أحكامه.\nالإقرار الضريبي:الإقرار المقدم من المسجل وفق أحكام المادة (١٦) من هذا القانون.\nالمدقق:موظف الدائرة المفوض من المدير بتدقيق الإقرارات الضريبية وتقدير الضريبة واحتساب أي مبالغ أخرى مترتبة على المكلف والقيام بأي مهام وواجبات أخرى منوطة به وفق أحكام القانون.\nهيئة الاعتراض:هيئة الاعتراض المشكلة بمقتضى أحكام هذا القانون.\nالمحكمة:المحكمة المختصة وفق أحكام هذا القانون.\nالتعليمات التنفيذية:التعليمات التي يصدرها الوزير بناءً على تنسيب المدير لتنفيذ أحكام هذا القانون وتنشر في الجريدة الرسمية.\nالتوريد:نقل ملكية السلع أو حق استخدامها كمالك وجميع التوريدات التي لا تعتبر توريدا للسلع تعتبر توريدا للخدمات.\nتوريد السلعة:بيع السلع من طرف الى آخر أو نقل حقوق الملكية فيها.\nتوريد الخدمة:جميع التوريدات التي لا تعتبر توريدا للسلع.\nاستيراد السلع:استيراد السلع وفق أحكام الفقرة (د) من المادة (٤ مكرر) من هذا القانون.\nاستيراد الخدمات:استيراد الخدمات وفق أحكام الفقرة (هـ) من المادة (٤ مكرر) من هذا القانون.\nالمنطقة الضريبية:الأراضي والمياه الإقليمية للمملكة باستثناء المناطق التنموية ومنطقة العقبة الاقتصادية الخاصة والمناطق الحرة والاسواق الحرة والمستودعات\nالمناطق الحرة:جزء من أراضي المملكة محدد ومسور بحاجز فاصل يخصص لغايات ممارسة الانشطة الاقتصادية والتجارية بما فيها تخزين السلع ويعتبر خارج النطاق الجمركي وتعامل السلع والانشطة الاقتصادية داخلها على انها خارج المنطقة الضريبية\nمنطقة العقبة:منطقة العقبة الاقتصادية الخاصة كما عرفها\nالاقتصادية الخاصة:قانون منطقة العقبة الاقتصادية الخاصة.\nالمستودع:هو المكان أو البناء الذي تودع فيه البضائع تحت إشراف دائرة الجمارك في وضع معلق للرسوم والضرائب.\nب- لمقاصد هذا القانون تحل عبارة (دائرة ضريبة الدخل والمبيعات) محل عبارة (دائرة الضريبة العامة على المبيعات) وتحل عبارة (مدير عام دائرة ضريبة الدخل والمبيعات) محل عبارة (مدير عام دائرة الضريبة العامة على المبيعات) حيثما ورد النص عليهما في أي تشريع نافذ المفعول أو أي تعليمات أو قرارات معمول بها.","title":"التعريفات","memo":"⭐ الشخص غير المقيم: أقام خارج المملكة أكثر من ١٨٣ يوماً خلال الـ١٢ شهراً السابقة لمغادرته\n⭐ السلعة تشمل الطاقة الكهربائية؛ الخدمة: كل عمل لقاء بدل ولا تشمل تزويد سلعة\n⭐ المنطقة الضريبية: أراضي المملكة ومياهها الإقليمية باستثناء المناطق التنموية والعقبة الخاصة والمناطق والأسواق الحرة والمستودعات\n⭐ التعليمات التنفيذية يصدرها الوزير بتنسيب المدير وتنشر في الجريدة الرسمية؛ المستورد مكلف ولو كان الاستيراد لأغراضه الخاصة","qs":[{"q":"وفقاً لتعريف (الشخص غير المقيم)، هو الشخص الطبيعي الذي أقام خارج المملكة مدة تزيد على:","o":["مائة وثلاثة وثمانين يوماً خلال الاثني عشر شهراً السابقة لتاريخ مغادرته","تسعين يوماً خلال الاثني عشر شهراً السابقة لتاريخ مغادرته","مائة وثمانين يوماً خلال السنة الميلادية السابقة","ستة أشهر متصلة قبل تاريخ مغادرته"],"a":0},{"q":"أي مما يلي لا يدخل ضمن (المنطقة الضريبية) وفق تعريفها في القانون؟","o":["منطقة العقبة الاقتصادية الخاصة","المياه الإقليمية للمملكة","أراضي محافظة إربد","أراضي محافظة العاصمة"],"a":0},{"q":"تصدر التعليمات التنفيذية لتنفيذ أحكام قانون الضريبة العامة على المبيعات من:","o":["الوزير بناءً على تنسيب المدير","مجلس الوزراء بناءً على تنسيب الوزير","المدير بناءً على تنسيب المدقق","هيئة الاعتراض بناءً على تنسيب المدير"],"a":0},{"q":"استورد شخص سلعة خاضعة للضريبة لاستعماله الخاص، فإنه وفق تعريف (المكلف):","o":["يعتبر مكلفاً وإن كان الاستيراد لأغراضه الخاصة","لا يعتبر مكلفاً لأن الاستيراد لأغراض خاصة","لا يعتبر مكلفاً إلا إذا تجاوز حد التسجيل","يعتبر مكلفاً فقط إذا كان مسجلاً اختيارياً"],"a":0}]},{"n":"3","chapter":"","notes":[],"source":"أ- تحدد السلع والخدمات الخاضعة للضريبة الخاصة بمقتضى الجدول رقم (١) الملحق بهذا القانون ويعتبر جزءًا لا يتجزأ منه.\nب-يصدر مجلس الوزراء بناء على تنسيب الوزير الجداول التالية:\n١. الجدول الخاص بالسلع والخدمات الخاضعة للضريبة بنسبة أو بمقدار (صفر) المشار إليه في هذا القانون بالجدول رقم (٢).\n٢. الجدول الخاص بالسلع والخدمات المعفاة من الضريبة المشار إليه في هذا القانون بالجدول رقم (٣).\n٣. الجدول الخاص بالسلع والخدمات والتي تكون الضريبة العامة والخاصة المستحقة عليها غير قابلة للخصم أو الرد المشار إليه في هذا القانون بالجدول رقم (٤).\nج- لمجلس الوزراء بناء على تنسيب مبرر من الوزير إجراء التعديل على أي من الجداول المنصوص عليها في الفقرة (ب) من هذه المادة بحذف أي من السلع أو الخدمات الواردة فيها أو بإضافة سلعة أو خدمة جديدة إليها أو نقل سلعة أو خدمة من جدول لآخر.","title":"جداول السلع والخدمات","memo":"⭐ الجدول (١): السلع والخدمات الخاضعة للضريبة الخاصة، ملحق بالقانون وجزء لا يتجزأ منه\n⭐ يصدر مجلس الوزراء بتنسيب الوزير: الجدول (٢) بنسبة (صفر)، الجدول (٣) المعفاة، الجدول (٤) غير القابلة للخصم أو الرد\n⭐ تعديل الجداول (حذف/إضافة/نقل) لمجلس الوزراء بناءً على تنسيب مبرر من الوزير","qs":[{"q":"الجدول الخاص بالسلع والخدمات المعفاة من الضريبة يشار إليه في القانون بالجدول رقم:","o":["(٣)","(١)","(٢)","(٤)"],"a":0},{"q":"الجهة التي تصدر الجدول الخاص بالسلع والخدمات الخاضعة للضريبة بنسبة (صفر) هي:","o":["مجلس الوزراء بناءً على تنسيب الوزير","الوزير بناءً على تنسيب المدير","المدير بناءً على تنسيب الوزير","مجلس النواب بناءً على تنسيب مجلس الوزراء"],"a":0},{"q":"الجدول رقم (٤) الملحق بالقانون يتضمن السلع والخدمات:","o":["التي تكون الضريبة المستحقة عليها غير قابلة للخصم أو الرد","الخاضعة للضريبة الخاصة","الخاضعة للضريبة بنسبة (صفر)","المعفاة من الضريبة"],"a":0}]},{"n":"4","chapter":"","notes":[],"source":"أ- يعد بيعاً لغايات هذا القانون انتقال ملكية السلعة أو أداء الخدمة أو توريدها من البائع إلى المشتري لقاء بدل، ويعد بيعا بحكم القانون استعمال السلعة من قبل المكلف لأغراضه الخاصة أو تمكين الغير من ذلك مقابل بدل أو بدون بدل أو التصرف فيها بأي من التصرفات القانونية الناقلة للملكية.\nب-يخضع للضريبة العامة ما يلي:\n١- بيع أي سلعة أو خدمة أو كلتيهما معاً داخل المنطقة الضريبية، إلا إذا كان هذا البيع غير خاضع للضريبة أو معفى منها بموجب أحكام هذا القانون.\n٢- استيراد أي سلعة أو خدمة إلى داخل المنطقة الضريبية إلا إذا كانت غير خاضعة للضريبة أو معفاة منها بموجب أحكام هذا القانون.\nج- دون الإخلال بأحكام الفقرة (ب) من هذه المادة، تخضع السلع المدرجة في الجدول رقم (١) الملحق بهذا القانون للضريبة الخاصة ولمرة واحدة في أي من الحالتين التاليتين:\n١- استيراد أي من تلك السلع إلى داخل المنطقة الضريبية.\n٢- وضع السلعة المنتجة محليا للتداول لأول مرة أو عند البيع الأول أو عند البيع اللاحق لهذه السلعة وفق تعليمات يضعها المدير لهذه الغاية.\nد- لغايات تطبيق أحكام هذا القانون، يعد توريداً للسلع أي من الحالات التالية:\n١- نقل ملكية السلع لشخص آخر أو تمكين شخص آخر من التصرف فيها كمالك.\n٢- إبرام عقد بين طرفين يترتب عليه نقل ملكية السلع في حال تنفيذ هذا العقد.\nهـ - يعد توريداً للخدمات كل توريد لا يعتبر توريداً للسلع.","title":"مفهوم البيع وما يخضع للضريبة","memo":"⭐ البيع: انتقال ملكية السلعة أو أداء الخدمة لقاء بدل؛ ويعد بيعاً بحكم القانون استعمال المكلف للسلعة لأغراضه الخاصة بدل أو بدون بدل\n⭐ تخضع للضريبة العامة: البيع داخل المنطقة الضريبية والاستيراد إليها\n⭐ سلع الجدول (١) تخضع للضريبة الخاصة لمرة واحدة عند الاستيراد أو الطرح للتداول/البيع الأول أو اللاحق وفق تعليمات المدير\n⭐ يعد توريداً للخدمات كل توريد لا يعتبر توريداً للسلع","qs":[{"q":"استعمل مكلف سلعة من بضاعته لأغراضه الخاصة دون مقابل، فإن ذلك وفق القانون:","o":["يعد بيعاً بحكم القانون","لا يعد بيعاً لعدم وجود بدل","يعد توريداً للخدمات","يعد استيراداً للسلعة"],"a":0},{"q":"تخضع السلع المدرجة في الجدول رقم (١) للضريبة الخاصة:","o":["لمرة واحدة","عند كل عملية بيع","مرتين: عند الاستيراد وعند البيع","سنوياً طوال فترة حيازتها"],"a":0},{"q":"أي مما يلي يعد توريداً للسلع لغايات القانون؟","o":["إبرام عقد بين طرفين يترتب عليه نقل ملكية السلع في حال تنفيذه","تقديم منفعة إلى الغير لقاء بدل","أداء عمل لقاء بدل لا يشمل تزويد سلعة","تقديم خدمات البث الإذاعي والتلفزيوني"],"a":0}]},{"n":"4 مكرر","chapter":"","notes":[],"source":"أ-يعتبر توريد السلع قد تم داخل المنطقة الضريبية في أي من الحالتين التاليتين:\n١- عندما يشتمل التوريد على النقل ويبدأ النقل من داخل المنطقة الضريبية.\n٢- عندما تكون السلع داخل المنطقة الضريبية وقت توريدها.\nب-دون الإخلال بأحكام الفقرة (أ) من هذه المادة، يعتبر توريد السلع إلى داخل المنطقة الضريبية قد تم في أي من الحالتين التاليتين:\n١- عندما يبدأ نقل السلع من خارج المنطقة الضريبية ويتولى المستورد أو أي شخص توريد السلع وتصبح في حيازته لاحقاً داخل المنطقة الضريبية.\n٢- السلع التي يتولى المورد تركيبها داخل المنطقة الضريبية أو يتولى تركيبها شخص آخر بالنيابة عنه.\nج- يعتبر توريد الخدمات قد تم داخل المنطقة الضريبية إذا تم تأدية العمل أو تقديم المنفعة المتعلقة بها في هذه المنطقة في أي من الحالات التالية:\n١- إذا كان المورد قد مارس عمله في المنطقة الضريبية.\n٢- إذا كان للمورد منشأة ثابتة في المنطقة الضريبية يتم التوريد منها.\n٣- إذا كان للمورد عنوان دائم في المنطقة الضريبية أو يقيم عادة في المنطقة الضريبية.\nد- يعتبر استيراد السلع قد تم إلى داخل المنطقة الضريبية عند إدخال البضائع إلى المنطقة الضريبية من أي مكان خارج المنطقة الضريبية.\nهـ -يعتبر استيراد الخدمات قد تم إلى داخل المنطقة الضريبية في أي من الحالات التالية:\n١- إذا كان متلقي الخدمة شخصا خاضعا للضريبة أسس مكان عمله داخل المنطقة الضريبية أو لديه منشأة ثابتة في المنطقة الضريبية يتم توفير الخدمات لها أو لديه عنوان دائم أو يقيم عادة في المنطقة الضريبية.\n٢- إذا كان متلقي الخدمة شخصا غير خاضع للضريبة أسس مكان عمله داخل المنطقة الضريبية وله عنوان دائم أو يقيم عادة في المنطقة الضريبية وتكون الخدمة احدى الخدمات المنصوص عليها في البند (٦) من هذه الفقرة.\n٣- أن تكون الخدمة مرتبطة بأموال غير منقولة موجودة في المنطقة الضريبية.\n٤- أن تكون الخدمة تتضمن مصادر دخل لأنشطة المناسبات الثقافية أو الفنية أو الرياضية أو العلمية أو التربوية أو الترفيهية أو ما يماثلها من الفعاليات التي تقام في المنطقة الضريبية.\n٥- أن تكون الخدمة من مطاعم أو خدمات تموينية يتم القيام بها فعلياً في المنطقة الضريبية.\n٦- أن تكون إحدى الخدمات التالية:\nأ- خدمات الاتصالات.\nب-خدمات البث الإذاعي والتلفزيوني.\nج- الخدمات الموردة الكترونيا.\nد- أي خدمات أخرى يحددها مجلس الوزراء بناء على تنسيب الوزير.","title":"مكان التوريد والاستيراد","memo":"⭐ توريد السلع داخل المنطقة الضريبية: إذا بدأ النقل منها أو كانت السلع فيها وقت التوريد\n⭐ توريد الخدمات داخلها: ممارسة العمل فيها أو منشأة ثابتة أو عنوان دائم/إقامة معتادة\n⭐ استيراد السلع: عند إدخال البضائع إلى المنطقة الضريبية من أي مكان خارجها\n⭐ من الخدمات المستوردة: الاتصالات، البث الإذاعي والتلفزيوني، الخدمات الموردة إلكترونياً، وأي خدمات يحددها مجلس الوزراء بتنسيب الوزير","qs":[{"q":"يعتبر توريد السلع قد تم داخل المنطقة الضريبية في حالة:","o":["كون السلع داخل المنطقة الضريبية وقت توريدها","انتهاء النقل خارج المنطقة الضريبية","سداد ثمن السلع من حساب بنكي خارج المملكة","تحرير العقد بلغة أجنبية"],"a":0},{"q":"أي من الخدمات التالية ليست من الخدمات المنصوص عليها صراحة في البند (٦) من الفقرة (هـ) من المادة؟","o":["الخدمات المصرفية","خدمات الاتصالات","خدمات البث الإذاعي والتلفزيوني","الخدمات الموردة إلكترونياً"],"a":0},{"q":"الجهة التي تملك تحديد خدمات أخرى تعتبر مستوردة إلى المنطقة الضريبية إضافة إلى الخدمات المنصوص عليها هي:","o":["مجلس الوزراء بناءً على تنسيب الوزير","الوزير بناءً على تنسيب المدير","المدير","دائرة الجمارك"],"a":0},{"q":"استأجرت شركة أجنبية مهندساً لتقديم خدمة مرتبطة بعقار موجود في عمّان، فإن الخدمة:","o":["تعتبر مستوردة إلى داخل المنطقة الضريبية لارتباطها بأموال غير منقولة فيها","لا تعتبر مستوردة لأن المورد أجنبي","لا تعتبر مستوردة إلا إذا دفع بدلها نقداً","تعتبر مصدرة إلى خارج المملكة"],"a":0}]},{"n":"5","chapter":"","notes":[],"source":"أ- تنفيذا لأحكام هذا القانون، ولأغراض تحديد مسميات السلع تعتمد جداول التعرفة وشروحاتها النافذة وفقا لأحكام قانون الجمارك، أما مسميات الخدمات فتعتمد بشأنها التصنيفات الدولية الصادرة عن الامانة العامة للأمم المتحدة.\nب-للمدير اعتبار المكلف بائعا لسلعة أو خدمة إذا قام ببيعها معاً وفي آن واحد حسب مقتضى الحال وللمكلف فصل حساباته الخاصة ببيع السلعة عن حساباته الخاصة ببيع الخدمة.\nج- لغايات هذا القانون تعتبر أي جهة تقوم ببيع أو استيراد سلع أو خدمات على أنها شخص بغض النظر عن صفتها.","title":"مسميات السلع والخدمات واعتبار الشخص","memo":"⭐ مسميات السلع: جداول التعرفة وشروحاتها وفق قانون الجمارك\n⭐ مسميات الخدمات: التصنيفات الدولية الصادرة عن الأمانة العامة للأمم المتحدة\n⭐ للمدير اعتبار المكلف بائعاً لسلعة أو خدمة إذا باعهما معاً، وللمكلف فصل حساباته\n⭐ أي جهة تبيع أو تستورد تعتبر شخصاً بغض النظر عن صفتها","qs":[{"q":"تعتمد في تحديد مسميات الخدمات لغايات القانون:","o":["التصنيفات الدولية الصادرة عن الأمانة العامة للأمم المتحدة","جداول التعرفة الجمركية وشروحاتها","تصنيفات وزارة الصناعة والتجارة","تعليمات يصدرها المدير"],"a":0},{"q":"تعتمد في تحديد مسميات السلع لغايات القانون:","o":["جداول التعرفة وشروحاتها النافذة وفقاً لأحكام قانون الجمارك","التصنيفات الدولية الصادرة عن الأمانة العامة للأمم المتحدة","قرارات مجلس الوزراء","تعليمات وزير الصناعة والتجارة"],"a":0},{"q":"مكلف يبيع سلعة وخدمة معاً وفي آن واحد، فإن القانون:","o":["يجيز للمدير اعتباره بائعاً لسلعة أو خدمة حسب مقتضى الحال، وله فصل حساباته","يلزمه بالتسجيل مرتين لدى الدائرة","يعفيه من الضريبة على الخدمة","يوجب على الوزير تحديد صفته بقرار"],"a":0}]},{"n":"6","chapter":"","notes":[],"source":"أ- تفرض بمقتضى هذا القانون ضريبة عامة على استيراد أي سلعة أو خدمة أو توريد أي منهما بنسبة (%١٦) من قيمة هذه السلعة أو بدل هذه الخدمة.\nب-مع مراعاة أحكام المادة (٣) من هذا القانون تخضع السلع والخدمات المدرجة في الجدول رقم (١) الملحق بهذا القانون لضريبة خاصة يحدد مقدارها ونسبتها وفئتها بمقتضى نظام يصدر لهذه الغاية.","title":"نسبة الضريبة العامة والخاصة","memo":"⭐ الضريبة العامة (%١٦) من قيمة السلعة أو بدل الخدمة على الاستيراد أو التوريد\n⭐ سلع وخدمات الجدول (١) تخضع لضريبة خاصة يحدد مقدارها ونسبتها وفئتها بنظام","qs":[{"q":"تفرض الضريبة العامة على استيراد أو توريد أي سلعة أو خدمة بنسبة:","o":["(%١٦)","(%١٠)","(%٢٠)","(%١٤)"],"a":0},{"q":"يحدد مقدار الضريبة الخاصة ونسبتها وفئتها على سلع وخدمات الجدول رقم (١) بمقتضى:","o":["نظام يصدر لهذه الغاية","تعليمات يصدرها المدير","قرار من الوزير","تعليمات تنفيذية يصدرها الوزير"],"a":0}]},{"n":"7","chapter":"","notes":[],"source":"أ- مع مراعاة أحكام الفقرة (ج) من هذه المادة تحتسب الضريبة العامة والضريبة الخاصة حسب مقتضى الحال بنسبة أو بمقدار (صفر) عند بيع أو استيراد أي من السلع والخدمات التالية:\n١. السلع الواردة في الجدول رقم (٢) الملحق بهذا القانون.\n٢. السلع والخدمات التي يتم بيعها إلى المناطق والمدن والأسواق الحرة أو تصديرها إلى خارج المملكة.\n٣. السلع والخدمات المباعة إلى الجهات المعفاة بمقتضى المادة (٢١) من هذا القانون ووفقا لأحكامها.\nب-تعفى من الضريبة السلع والخدمات المنصوص عليها في الجدول رقم (٣) الملحق بهذا القانون.\nج- مع مراعاة أحكام الفقرة (د) من هذه المادة يخضع بيع أي سلعة أو خدمة واردة في أي من الجدولين رقم (٢) و(٣) الملحقين بهذا القانون للضريبة العامة إذا كان بيعها مصحوباً أو مرتبطاً بسلعة أو خدمة أخرى خاضعة لهذه الضريبة.\nد- إذا بيعت أي من الخدمات المالية المعفاة الواردة في الجدول رقم ٣ الملحق بهذا القانون وكان هذا البيع مرتبطاً أو منطوياً على بيع سلعة خاضعة للضريبة فان بيع هذه السلعة يبقى خاضعاً للضريبة على أساس قيمتها قبل ارتباطها بالخدمة المعفاة.","title":"النسبة الصفرية والإعفاء","memo":"⭐ (صفر): سلع الجدول (٢)، المبيع للمناطق والمدن والأسواق الحرة أو المصدّر، والمبيع للجهات المعفاة بالمادة (٢١)\n⭐ سلع وخدمات الجدول (٣) معفاة\n⭐ سلع الجدولين (٢) و(٣) تخضع للضريبة العامة إذا بيعت مصحوبة أو مرتبطة بسلعة/خدمة خاضعة\n⭐ الخدمة المالية المعفاة المرتبطة بسلعة خاضعة: تبقى السلعة خاضعة على أساس قيمتها قبل ارتباطها","qs":[{"q":"أي مما يلي لا تحتسب عليه الضريبة بنسبة (صفر) بموجب الفقرة (أ) من المادة (٧)؟","o":["السلع والخدمات المنصوص عليها في الجدول رقم (٣)","السلع الواردة في الجدول رقم (٢)","السلع والخدمات المصدرة إلى خارج المملكة","السلع والخدمات المباعة إلى الجهات المعفاة بمقتضى المادة (٢١)"],"a":0},{"q":"بيعت سلعة واردة في الجدول رقم (٢) مصحوبة بسلعة أخرى خاضعة للضريبة العامة، فإن بيعها:","o":["يخضع للضريبة العامة","يبقى خاضعاً بنسبة (صفر)","يصبح معفى من الضريبة","يخضع للضريبة الخاصة فقط"],"a":0},{"q":"بيعت خدمة مالية معفاة مرتبطة ببيع سلعة خاضعة للضريبة، فإن السلعة:","o":["تبقى خاضعة للضريبة على أساس قيمتها قبل ارتباطها بالخدمة المعفاة","تعفى تبعاً للخدمة المالية","تخضع بنسبة (صفر)","تخضع للضريبة على أساس قيمتها مضافاً إليها قيمة الخدمة المالية"],"a":0}]},{"n":"8","chapter":"","notes":[],"source":"يلتزم المسجل بتحصيل الضريبة وبالإقرار عنها وتوريدها للدائرة في المواعيد المحددة في هذا القانون.","title":"التزام المسجل بالتحصيل والتوريد","memo":"⭐ المسجل ملزم بتحصيل الضريبة والإقرار عنها وتوريدها للدائرة في المواعيد المحددة في القانون","qs":[{"q":"يلتزم بتحصيل الضريبة والإقرار عنها وتوريدها للدائرة في المواعيد المحددة:","o":["المسجل","المشتري النهائي","المدقق","دائرة الجمارك"],"a":0}]},{"n":"9","chapter":"","notes":[],"source":"أ- تستحق الضريبة العامة والخاصة على توريد السلعة عند وقوع أي من الحالات التالية أيها أسبق:\n١- نقل ملكية السلعة وللمدير اعتماد تاريخ الفاتورة الضريبية لغايات استحقاق الضريبة إذا كانت هذه الفاتورة تصدر بشكل دوري أو في نهاية مدة معينة بعد تاريخ نقل ملكية.\n٢- إصدار فاتورة ضريبية.\n٣- تسليم قيمة السلعة كليا أو جزئيا أو تسلم دفعة منها بالأجل أو بغير ذلك من طرق تسلم القيمة وفقا لشروط الدفع المتفق عليها.\nب-تستحق الضريبة على بيع الخدمة عند وقوع أي من الحالتين التاليتين أيهما أسبق:\n١- توريد الخدمة.\n٢- إصدار فاتورة ضريبية.\n٣- تسلم بدل الخدمة كليا أو جزئيا.\nج- تستحق الضريبة في أي من الحالات المنصوص عليها في الفقرتين (أ) و(ب) من هذه المادة على أساس قيمة الفاتورة الضريبية أو ما تم دفعه من قيمة السلعة أو بدل الخدمة أيهما أعلى.\nد-\n١. تستحق الضريبة العامة والخاصة على السلعة المستوردة في مرحلة التخليص عليها حسب نسبة الضريبة أو فئتها في تاريخ تسجيل البيان الجمركي.\n٢. يتم تحصيل الضريبة العامة والخاصة عن السلع المستوردة في مرحلة التخليص عليها وفقا لأحكام قانون الجمارك ما لم يرد نص في هذا القانون يقضي بغير ذلك.\nهـ - مع مراعاة اتفاقيات الازدواج الضريبي، تستحق الضريبة على الخدمة المستوردة عند دفع بدل هذه الخدمة كليا أو جزئيا ويلتزم متلقيها أو المستفيد منها بدفع الضريبة المستحقة عليها الى الدائرة.\nو- تستحق الضريبة العامة والخاصة على بيع السلعة أو الخدمة داخل المناطق والمدن والأسواق الحرة عند الاستفادة من تلك السلعة أو الخدمة لأغراض شخصية أو لأغراض غير متعلقة بمزاولة العمل المرخص به داخل تلك المناطق والمدن والأسواق الحرة.\nز- باستثناء الحالات المنصوص عليها في هذه المادة، للوزير ولأسباب مبررة أن يصدر تعليمات تنفيذية لتحديد واقعة تحقق الضريبة على بيع السلعة أو الخدمة بما في ذلك حالة بيع السلعة أو الخدمة لقاء بدل يتم تحديده بشكل دوري أو من وقت لآخر أو في نهاية مدة معينة أو بعد أن يتم استعمال تلك السلعة.","title":"واقعة استحقاق الضريبة","memo":"⭐ السلعة: تستحق عند الأسبق من نقل الملكية أو إصدار الفاتورة الضريبية أو تسلم القيمة كلياً أو جزئياً\n⭐ الخدمة: الأسبق من توريدها أو إصدار الفاتورة أو تسلم بدلها\n⭐ الأساس: قيمة الفاتورة أو المدفوع أيهما أعلى؛ المستوردة: عند التخليص حسب النسبة بتاريخ تسجيل البيان الجمركي\n⭐ الخدمة المستوردة: عند دفع بدلها كلياً أو جزئياً ويلتزم متلقيها بالدفع","qs":[{"q":"تستحق الضريبة على توريد السلعة عند وقوع أي من الحالات المحددة في القانون:","o":["أيها أسبق","أيها أحدث","أيها أعلى قيمة","بعد مرور شهر على آخرها"],"a":0},{"q":"تستحق الضريبة على السلعة المستوردة حسب نسبة الضريبة أو فئتها في تاريخ:","o":["تسجيل البيان الجمركي","وصول السلعة إلى المخازن","بيع السلعة لأول مرة داخل المملكة","إصدار الفاتورة الأجنبية"],"a":0},{"q":"أصدر مسجل فاتورة ضريبية بقيمة (١٠٠٠٠) دينار وتسلم دفعة بقيمة (١٢٠٠٠) دينار، فإن الضريبة تستحق على أساس:","o":["(١٢٠٠٠) دينار لأنه أعلى","(١٠٠٠٠) دينار قيمة الفاتورة","متوسط المبلغين","(٢٠٠٠) دينار الفرق بينهما"],"a":0},{"q":"يلتزم بدفع الضريبة المستحقة على الخدمة المستوردة إلى الدائرة:","o":["متلقي الخدمة أو المستفيد منها","المورد الأجنبي للخدمة","دائرة الجمارك","البنك الذي حوّل بدل الخدمة"],"a":0}]},{"n":"10","chapter":"","notes":[],"source":"لا يخضع للضريبة ما يلي:\nأ- بيع السلعة أو الخدمة إذا تم بعد الاستفادة منها لأغراض شخصية أو لأغراض غير متعلقة بمزاولة العمل الخاضع للضريبة المرخص به للمكلف وفق أحكام هذا القانون ولم يسبق للمكلف أن خصم أو رد الضريبة المستوفاة على هذه السلعة أو الخدمة.\nب-بيع الأموال غير المنقولة.\nج- بيع الحصص والأسهم في الشركات وصناديق الاستثمار والأوراق المالية على اختلاف أنواعها.\nد- ما يتقاضاه الموظفون والمستخدمون والعاملون مقابل خدمتهم أو مقابل ما هو مرتبط بخدمتهم لدى الوزارات والدوائر الحكومية والمؤسسات الرسمية وغيرها من أشخاص القطاع العام وكل ما يتقاضاه المستخدمون والعاملون مقابل عملهم او مقابل ما هو مرتبط بعملهم لدى اصحاب العمل بما في ذلك المكافآت وأي مبالغ أخرى يتم دفعها إلى أعضاء مجالس إدارة الأشخاص الاعتباريين.\nهـ - السلع والخدمات التي يتم استيرادها لحساب المشاريع القائمة في المناطق والمدن والأسواق الحرة من خارج المملكة وفي حدود ما يقتضيه تنفيذ غاياتها وفقا للتشريعات الخاصة بها على أن يقتصر عدم خضوعها للضريبة على أعمالها التي تمارسها داخل هذه المناطق والمدن والأسواق الحرة.\nو- السلع والخدمات التي يتم تصديرها من المناطق والمدن والأسواق الحرة إلى خارج المملكة.","title":"ما لا يخضع للضريبة","memo":"⭐ لا تخضع: بيع الأموال غير المنقولة، بيع الحصص والأسهم والأوراق المالية\n⭐ لا تخضع: رواتب ومكافآت الموظفين والعاملين وأعضاء مجالس الإدارة\n⭐ لا تخضع: مستوردات مشاريع المناطق الحرة لغاياتها داخلها، والصادرات منها إلى خارج المملكة\n⭐ بيع السلعة بعد الاستفادة منها لأغراض شخصية إذا لم يسبق خصم أو رد ضريبتها","qs":[{"q":"أي مما يلي لا يخضع للضريبة العامة على المبيعات؟","o":["بيع الأموال غير المنقولة","بيع السيارات المستعملة من قبل معرض مسجل","خدمات المطاعم داخل المنطقة الضريبية","بيع الأجهزة الكهربائية"],"a":0},{"q":"المكافآت المدفوعة لأعضاء مجالس إدارة الأشخاص الاعتباريين:","o":["لا تخضع للضريبة","تخضع للضريبة العامة بنسبة (%١٦)","تخضع للضريبة الخاصة","تخضع بنسبة (صفر)"],"a":0},{"q":"باع مكلف سيارة استعملها لأغراضه الشخصية ولم يسبق له خصم أو رد الضريبة المستوفاة عليها، فإن هذا البيع:","o":["لا يخضع للضريبة","يخضع للضريبة العامة على كامل قيمته","يخضع للضريبة الخاصة فقط","يخضع للضريبة على أساس سعر الكلفة"],"a":0}]},{"n":"11","chapter":"","notes":[],"source":"في حالة التوقف عن ممارسة نشاط يتعلق بسلعة خاضعة للضريبة أو تصفيته تستحق الضريبة على تلك السلع التي آلت إلى الخلف القانوني وقت التصرف بها إلا إذا كان الخلف مسجلاً أو قام بتسجيل نفسه وفقاً لأحكام هذا القانون.","title":"التوقف عن النشاط أو تصفيته","memo":"⭐ عند التوقف أو التصفية تستحق الضريبة على السلع التي آلت إلى الخلف القانوني وقت التصرف بها\n⭐ لا تستحق إذا كان الخلف مسجلاً أو قام بتسجيل نفسه","qs":[{"q":"صفّى مكلف نشاطه الخاضع للضريبة وآلت سلعه إلى خلفه القانوني، فإن الضريبة تستحق على تلك السلع:","o":["وقت التصرف بها، إلا إذا كان الخلف مسجلاً أو سجل نفسه","فوراً بتاريخ قرار التصفية في جميع الأحوال","لا تستحق مطلقاً لانتقالها بالخلافة","بعد خمس سنوات من التصفية"],"a":0},{"q":"لا تستحق الضريبة على السلع التي آلت إلى الخلف القانوني عند التصفية في حال:","o":["كان الخلف مسجلاً أو قام بتسجيل نفسه وفق أحكام القانون","كانت السلع مستوردة","كان الخلف شخصاً اعتبارياً","لم يتجاوز عدد الورثة ثلاثة"],"a":0}]},{"n":"12","chapter":"","notes":[],"source":"تخضع للضريبة السلع والخدمات التي تعتبر مهربة أو مخالفة لأحكام هذا القانون حسب فئات الضريبة النافذة في تاريخ وقوع التهرب أو المخالفة، فإذا تعذر تحديد هذا التاريخ فتخضع لفئات الضريبة النافذة وقت ضبط الجريمة أو المخالفة.","title":"ضريبة السلع المهربة والمخالفة","memo":"⭐ تخضع حسب فئات الضريبة النافذة في تاريخ وقوع التهرب أو المخالفة\n⭐ إذا تعذر تحديده: الفئات النافذة وقت ضبط الجريمة أو المخالفة","qs":[{"q":"تخضع السلع المهربة للضريبة حسب فئات الضريبة النافذة في:","o":["تاريخ وقوع التهرب أو المخالفة","تاريخ صدور الحكم القطعي","تاريخ دفع الغرامة","تاريخ التسوية الصلحية"],"a":0},{"q":"إذا تعذر تحديد تاريخ وقوع التهرب، تخضع السلع لفئات الضريبة النافذة:","o":["وقت ضبط الجريمة أو المخالفة","وقت صدور الحكم القطعي","في بداية السنة المالية","وقت إصدار الفاتورة"],"a":0}]},{"n":"13","chapter":"","notes":[],"source":"أ- يلتزم الشخص الذي يقوم ببيع سلعة أو خدمة خاضعة للضريبة بالتسجيل لدى الدائرة على الانموذج المعد لهذه الغاية وذلك عند حلول أي من التواريخ التالية أيها أسبق:\n١- تاريخ البدء بمزاولة عمل جديد يتعلق ببيع سلع أو خدمات خاضعة للضريبة إذا تبين أن سلعته خلال الاثني عشر شهرا التالية لمزاولة هذا العمل قد تتجاوز حد التسجيل المعين بمقتضى أحكام المادة (١٤) من هذا القانون.\n٢- نهاية فترة اثني عشر شهراً متتالية تبلغ فيها قيمة مبيعات الشخص من السلع والخدمات الخاضعة للضريبة حد التسجيل المعين بموجب أحكام المادة (١٤) من هذا القانون.\n٣- نهاية فترة أحد عشر شهراً متتالية يتبين فيها للشخص أن قيمة مبيعاته من السلع والخدمات الخاضعة للضريبة قد تبلغ حد التسجيل المعين بموجب أحكام المادة (١٤) من هذا القانون خلال الفترة المذكورة وأول شهر لاحق لها.\nب- يلتزم الشخص الذي يقوم باستيراد سلعة أو خدمة خاضعة للضريبة بالتسجيل لدى الدائرة على الانموذج المعد لهذه الغاية خلال ثلاثين يوماً من تاريخ أول استيراد له مهما بلغ حجم مستورداته إلا إذا كان الاستيراد للاستعمال الشخصي.\nج- إذا تخلف المكلف عن التسجيل لدى الدائرة في الموعد المحدد للتسجيل بموجب هذا القانون، فللمدير الموافقة على تسجيله اعتباراً من تاريخ التزامه بالتسجيل وفقا لأحكام الفقرة (أ) من هذه المادة.\nد- تقيد الدائرة طلبات التسجيل التي تقدم إليها بموجب الفقرة (أ) من هذه المادة في سجل خاص تعده لهذه الغاية وذلك بعد مراجعتها والتحقق من صحتها وتسلم لكل مسجل شهادة بذلك.\nهـ - يترتب على كل مسجل إعلام الدائرة خطياً بأية تغييرات تطرأ على البيانات الواردة في طلب التسجيل وذلك خلال (٣٠) يوماً من حدوث تلك التغييرات.\nو- تحدد التعليمات التنفيذية نموذج طلب التسجيل والبيانات الواجب إثباتها فيه والشروط والقواعد والمدد والإعلانات والإجراءات الخاصة بالتسجيل والشهادة التي يتم إصدارها.","title":"التسجيل الإلزامي","memo":"⭐ البائع يسجل عند الأسبق: بدء عمل جديد يتوقع تجاوزه حد التسجيل خلال ١٢ شهراً، نهاية ١٢ شهراً بلغ فيها الحد، نهاية ١١ شهراً يتبين معها بلوغ الحد مع الشهر اللاحق\n⭐ المستورد يسجل خلال ٣٠ يوماً من أول استيراد مهما بلغ حجمه إلا للاستعمال الشخصي\n⭐ للمدير الموافقة على تسجيل المتخلف اعتباراً من تاريخ التزامه\n⭐ إعلام الدائرة خطياً بتغيير بيانات التسجيل خلال (٣٠) يوماً","qs":[{"q":"يلتزم مستورد السلعة أو الخدمة الخاضعة للضريبة بالتسجيل لدى الدائرة خلال:","o":["ثلاثين يوماً من تاريخ أول استيراد له مهما بلغ حجم مستورداته","ستين يوماً من تاريخ أول استيراد له","ثلاثين يوماً من بلوغ مستورداته حد التسجيل","أسبوع من تاريخ أول استيراد له"],"a":0},{"q":"يلتزم المسجل بإعلام الدائرة خطياً بأية تغييرات تطرأ على بيانات طلب التسجيل خلال:","o":["(٣٠) يوماً من حدوثها","(١٥) يوماً من حدوثها","(٦٠) يوماً من حدوثها","أسبوع من حدوثها"],"a":0},{"q":"تخلف مكلف عن التسجيل في الموعد المحدد، فإن للمدير:","o":["الموافقة على تسجيله اعتباراً من تاريخ التزامه بالتسجيل","رفض تسجيله نهائياً","تسجيله اعتباراً من بداية السنة التالية فقط","إحالته إلى هيئة الاعتراض لتقرير تسجيله"],"a":0},{"q":"أي مما يلي لا يعتبر من تواريخ الالتزام بالتسجيل للبائع وفق الفقرة (أ)؟","o":["نهاية فترة ستة أشهر متتالية بلغت فيها المبيعات نصف حد التسجيل","نهاية فترة اثني عشر شهراً متتالية بلغت فيها المبيعات حد التسجيل","نهاية فترة أحد عشر شهراً متتالية يتبين معها بلوغ الحد خلالها وأول شهر لاحق","تاريخ البدء بعمل جديد يتوقع تجاوزه حد التسجيل خلال الاثني عشر شهراً التالية"],"a":0}]},{"n":"14","chapter":"","notes":[],"source":"أ- يعين حد التسجيل بنظام يصدر بمقتضى أحكام هذا القانون.\nب-يجوز للشخص الذي لم تبلغ قيمة مبيعاته من السلع أو الخدمات الخاضعة للضريبة حد التسجيل أن يقدم طلباً إلى الدائرة لتسجيله، وتسري عليه في هذه الحالة الأحكام الخاصة بالمسجل الواردة في هذا القانون.\nج- على الرغم مما ورد في أي تشريع آخر، إذا اشترك أكثر من شخص في بيع سلعة أو خدمة وكان أي منهم غير مسجل، وكانت مبيعاتهم من السلع والخدمات الخاضعة للضريبة متعلقة بمهنة او حرفة او اختصاص واحد ويمارسون اعمالهم معاً أو في موقع واحد يعتبرون لمقاصد حد التسجيل شخصاً واحداً عند احتساب قيمة مبيعاتهم الخاضعة للضريبة.\nد- يلغى بقرار من المدير تسجيل أي مكلف في أي من الحالات التالية:\n١- إذا ثبت أن المكلف لم يعد يمارس بيع سلع أو خدمات خاضعة للضريبة وفق أحكام هذا القانون.\n٢- إذا تقدم المكلف بطلب لإلغاء تسجيله لأنه أصبح غير ملزم بالتسجيل وفق أحكام هذا القانون، ويسري مفعول إلغاء التسجيل في نهاية الفترة الضريبية التي قدم خلالها هذا الطلب.\nهـ -\n١- تستحق الضريبة على جميع السلع الخاضعة لها والتي تكون في حوزة الشخص عند إلغاء تسجيله وفقا لأحكام الفقرة (د) من هذه المادة، وتحتسب الضريبة على أساس سعر السلعة السائد في السوق أو سعر الكلفة بتاريخ إلغاء التسجيل أيهما أقل.\n٢- يلتزم الشخص الذي تم إلغاء تسجيله وفقا لأحكام الفقرة (د) من هذه المادة بتقديم إقرار ضريبي نهائي ودفع الضريبة وأي مبالغ أخرى مستحقة عليه للدائرة في الموعد المحدد له.\nو- إذا كانت الضريبة المفروضة على جميع مبيعات المكلف من السلع أو الخدمات الخاضعة للضريبة بنسبة (صفر)، يجوز للمدير بناء على طلب المكلف أن يقرر إعفاءه من التسجيل، وإذا طرا أي تغيير بحيث أصبح أي جزء من مبيعات ذلك المكلف خاضعاً للضريبة بنسبة أخرى يلتزم المكلف المذكور بتقديم طلب لإعادة تسجيله خلال ثلاثين يوما من تاريخ وقوع ذلك التغيير.","title":"حد التسجيل وإلغاء التسجيل","memo":"⭐ يعين حد التسجيل بنظام؛ ويجوز التسجيل الاختياري لمن لم يبلغ الحد\n⭐ المشتركون في مهنة واحدة ويمارسون معاً أو بموقع واحد وأحدهم غير مسجل يعتبرون شخصاً واحداً لحد التسجيل\n⭐ يلغى التسجيل بقرار من المدير؛ وبطلب المكلف يسري الإلغاء في نهاية الفترة الضريبية التي قدم فيها الطلب\n⭐ عند الإلغاء: الضريبة على السلع بحوزته على أساس سعر السوق أو الكلفة أيهما أقل؛ معفى التسجيل (صفر) يعيد التسجيل خلال ٣٠ يوماً من التغيير","qs":[{"q":"يعين حد التسجيل لغايات الضريبة العامة على المبيعات بموجب:","o":["نظام يصدر بمقتضى أحكام القانون","تعليمات يصدرها المدير","قرار من الوزير","نص صريح في المادة (١٤)"],"a":0},{"q":"تحتسب الضريبة على السلع التي في حوزة الشخص عند إلغاء تسجيله على أساس:","o":["سعر السوق أو سعر الكلفة بتاريخ إلغاء التسجيل أيهما أقل","سعر السوق أو سعر الكلفة أيهما أعلى","سعر الكلفة التاريخية بتاريخ الشراء","القيمة التي يحددها المدقق"],"a":0},{"q":"قدم مكلف طلباً لإلغاء تسجيله لأنه أصبح غير ملزم بالتسجيل، فإن الإلغاء يسري:","o":["في نهاية الفترة الضريبية التي قدم خلالها الطلب","من تاريخ تقديم الطلب","بعد ثلاثين يوماً من تقديم الطلب","في نهاية السنة المالية"],"a":0},{"q":"مكلف جميع مبيعاته خاضعة بنسبة (صفر) وأعفاه المدير من التسجيل، ثم أصبح جزء من مبيعاته خاضعاً بنسبة أخرى، فعليه طلب إعادة التسجيل خلال:","o":["ثلاثين يوماً من تاريخ وقوع التغيير","ستين يوماً من تاريخ وقوع التغيير","نهاية الفترة الضريبية التالية","أسبوع من تاريخ وقوع التغيير"],"a":0}]},{"n":"15","chapter":"","notes":[],"source":"أ-\n١- يلتزم المسجل عند تقديم الإقرار الضريبي بالتصريح بالقيمة الحقيقية لبيع السلعة ليتم احتساب مقدار الضريبة على أساسها.\n٢- يعتبر الثمن الذي يلتزم المشتري بدفعه للبائع مقابل السلعة أو الخدمة هو القيمة الحقيقية لبيع أي منهما.\n٣- للمدير أن يتحقق من القيمة الحقيقية لبيع السلعة أو الخدمة بالطلب من المكلف تزويده بجميع الوثائق والسجلات المتعلقة بعملية البيع.\nب-تضاف قيمة الضريبة الخاصة المستحقة على بيع السلعة أو الخدمة إلى قيمتها الحقيقية لغايات احتساب الضريبة العامة عليها.\nج- يحدد مقدار الضريبة العامة على السلع المستوردة باعتماد القيمة المتخذة أساسا لتحديد الرسوم الجمركية وفقا لجداول التعرفة المطبقة مضافا إليها أي رسوم وضرائب مستحقة قبل التخليص عليها بما في ذلك الضريبة الخاصة المستحقة عليها وفق أحكام هذا القانون.\nد- إذا كان بدل بيع السلعة أو الخدمة الخاضعة للضريبة محدداً بعملة أجنبية، فيتم تحويلها إلى الدينار الأردني على أساس سعر الصرف بتاريخ تحقق واقعة البيع.\nهـ - تطبق أحكام هذه المادة على السلع أو الخدمات التي ارتكبت بشأنها أي مخالفة لأحكام هذا القانون بما في ذلك التهرب من دفع الضريبة عليها.","title":"القيمة الخاضعة للضريبة","memo":"⭐ القيمة الحقيقية: الثمن الذي يلتزم المشتري بدفعه للبائع\n⭐ تضاف الضريبة الخاصة إلى القيمة الحقيقية لاحتساب الضريبة العامة\n⭐ المستوردات: القيمة الجمركية + الرسوم والضرائب قبل التخليص بما فيها الضريبة الخاصة\n⭐ العملة الأجنبية تحول للدينار بسعر الصرف بتاريخ تحقق واقعة البيع","qs":[{"q":"لغايات احتساب الضريبة العامة على سلعة خاضعة للضريبة الخاصة:","o":["تضاف قيمة الضريبة الخاصة إلى القيمة الحقيقية للسلعة","تطرح الضريبة الخاصة من القيمة الحقيقية","لا تحتسب الضريبة العامة على هذه السلعة","تحتسب كل ضريبة على حدة دون إضافة"],"a":0},{"q":"إذا كان بدل بيع السلعة محدداً بعملة أجنبية، يتم تحويله إلى الدينار على أساس سعر الصرف بتاريخ:","o":["تحقق واقعة البيع","تقديم الإقرار الضريبي","دفع الضريبة","نهاية الفترة الضريبية"],"a":0},{"q":"يعتبر القيمة الحقيقية لبيع السلعة أو الخدمة وفق القانون:","o":["الثمن الذي يلتزم المشتري بدفعه للبائع","سعر الكلفة لدى البائع","سعر السوق السائد","القيمة التي يقدرها المدقق"],"a":0}]},{"n":"16","chapter":"","notes":[],"source":"أ-\n١- على المسجل الملزم بدفع الضريبة العامة أن يقدم للدائرة كل شهرين إقرارا بمبيعاته من السلع والخدمات تحدد فيه قيمتها ومقدار الضريبة العامة المستحقة عليها، وتعتبر مدة الشهرين فترة ضريبية واحدة.\n٢- على المسجل الملزم بدفع الضريبة الخاصة أن يقدم للدائرة إقرارا شهريا بقيمة مبيعاته من السلع والخدمات الخاضعة للضريبة الخاصة ومقدار الضريبة المستحقة عليها، وتعتبر مدة الشهر فترة ضريبية واحدة.\n٣- يحدد المدير للمسجل بداية الفترة الضريبية ونهايتها.\n٤- على الرغم مما ورد في البندين (١) و (٢) من هذه الفقرة، يجوز للمدير وفي حالات خاصة تمديد الفترة الضريبية للمسجل على ألا تتجاوز بأي حال ستة أشهر.\nب-\n١- يلتزم المسجل بتقديم الإقرار على الانموذج المعتمد من الدائرة عن كل فترة ضريبية حتى وإن لم يحقق أي مبيعات خلالها سواء كان الإقرار خطيا أو باستخدام أسلوب معالجة المعلومات أو البيانات.\n٢- يلتزم المسجل بدفع الضريبة المستحقة عليه خلال الشهر التالي لانتهاء الفترة الضريبية وللمدير منح المسجل مدة إضافية لهذه الغاية لا تزيد على شهر واحد.","title":"الإقرار الضريبي والفترة الضريبية","memo":"⭐ الضريبة العامة: إقرار كل شهرين (فترة ضريبية واحدة)؛ الضريبة الخاصة: إقرار شهري\n⭐ يحدد المدير بداية الفترة ونهايتها، ويجوز تمديدها في حالات خاصة على ألا تتجاوز ستة أشهر\n⭐ يقدم الإقرار عن كل فترة حتى لو لم تتحقق مبيعات\n⭐ الدفع خلال الشهر التالي لانتهاء الفترة، وللمدير مدة إضافية لا تزيد على شهر","qs":[{"q":"الفترة الضريبية للمسجل الملزم بدفع الضريبة العامة هي:","o":["شهران","شهر واحد","ثلاثة أشهر","ستة أشهر"],"a":0},{"q":"يجوز للمدير في حالات خاصة تمديد الفترة الضريبية للمسجل على ألا تتجاوز بأي حال:","o":["ستة أشهر","ثلاثة أشهر","أربعة أشهر","اثني عشر شهراً"],"a":0},{"q":"مسجل لم يحقق أي مبيعات خلال الفترة الضريبية، فإنه:","o":["يلتزم بتقديم الإقرار عن تلك الفترة","يعفى من تقديم الإقرار عنها","يقدم الإقرار في نهاية السنة فقط","يكتفي بإشعار خطي للمدقق"],"a":0},{"q":"يلتزم المسجل بدفع الضريبة المستحقة خلال الشهر التالي لانتهاء الفترة الضريبية، ويجوز للمدير منحه مدة إضافية لا تزيد على:","o":["شهر واحد","خمسة عشر يوماً","شهرين","ثلاثة أشهر"],"a":0}]},{"n":"17","chapter":"","notes":[],"source":"تضاف الضريبة إلى سعر السلع أو الخدمات بما في ذلك السلع والخدمات المسعرة جبرياً والمحددة الربح.\nويشترط في ذلك أن يعدل حكماً السعر المتعاقد عليه لأي سلعة أو خدمة بحيث يصبح شاملاً للسعر مضافا إليه الضريبة المحدثة على السلعة أو الخدمة وملزماً لطرفي العقد في القطاعين العام والخاص اعتباراً من تاريخ سريان الضريبة شريطة أن يتم ذلك بالتقاص مع ضريبة الاستهلاك إن كانت قائمة.","title":"إضافة الضريبة إلى السعر","memo":"⭐ تضاف الضريبة إلى سعر السلع والخدمات بما فيها المسعرة جبرياً ومحددة الربح\n⭐ يعدل السعر المتعاقد عليه حكماً ليشمل الضريبة ويلزم الطرفين في القطاعين العام والخاص من تاريخ سريانها، بالتقاص مع ضريبة الاستهلاك إن كانت قائمة","qs":[{"q":"تضاف الضريبة إلى سعر السلع أو الخدمات:","o":["بما في ذلك السلع والخدمات المسعرة جبرياً والمحددة الربح","باستثناء السلع المسعرة جبرياً","باستثناء عقود القطاع العام","فقط إذا وافق المشتري على ذلك"],"a":0},{"q":"بعد سريان الضريبة على سلعة متعاقد عليها مسبقاً، فإن السعر المتعاقد عليه:","o":["يعدل حكماً ليصبح شاملاً للضريبة وملزماً لطرفي العقد","يبقى كما هو ويتحمل البائع الضريبة","يعدل فقط باتفاق جديد بين الطرفين","يفسخ العقد حكماً"],"a":0}]},{"n":"18","chapter":"","notes":[],"source":"أ- يلتزم المسجل بأن يحرر فاتورة ضريبية عن بيع السلعة أو الخدمة الخاضعة للضريبة وفق التعليمات التنفيذية.\nب-إذا قام شخص غير مسجل ببيع سلعة أو خدمة خاضعة للضريبة فللمدير إلزامه بإصدار فواتير ومسك سجلات وحسابات منتظمة لتسجيل عمليات البيع التي يقوم بها والاحتفاظ بتلك الفواتير والسجلات مدة الخمس سنوات التالية لتاريخ انتهاء السنة المالية التي صدرت أو نظمت فيها.","title":"الفاتورة الضريبية","memo":"⭐ المسجل ملزم بتحرير فاتورة ضريبية عن بيع السلعة أو الخدمة الخاضعة وفق التعليمات التنفيذية\n⭐ للمدير إلزام غير المسجل بإصدار فواتير ومسك سجلات والاحتفاظ بها خمس سنوات تالية لانتهاء السنة المالية","qs":[{"q":"يجوز للمدير إلزام الشخص غير المسجل الذي يبيع سلعاً خاضعة بالاحتفاظ بالفواتير والسجلات مدة:","o":["الخمس سنوات التالية لتاريخ انتهاء السنة المالية التي صدرت فيها","الأربع سنوات التالية لتاريخ تقديم الإقرار","ثلاث سنوات من تاريخ إصدارها","عشر سنوات من تاريخ إصدارها"],"a":0},{"q":"يحرر المسجل الفاتورة الضريبية عن بيع السلعة أو الخدمة الخاضعة للضريبة وفق:","o":["التعليمات التنفيذية","نظام يصدره مجلس الوزراء","قرار من هيئة الاعتراض","معايير المحاسبة الدولية فقط"],"a":0}]},{"n":"19","chapter":"","notes":[],"source":"للمسجل عند احتساب رصيد الضريبة المستحقة عليه وقبل دفعه الى الدائرة أن يخصم من مقدار الضريبة المستحقة على مبيعاته ما يلي:\nأ- ما سبق له احتسابه أو دفعه من ضريبة عامة أو ضريبة خاصة على المرتجع من مبيعاته.\nب-ما سبق له احتسابه أو دفعه من ضريبة عامة على مبيعاته المؤجلة الدفع التي أصبحت في عداد الديون المعدومة.\nج- ما سبق له تحمله من ضريبة عامة على مشترياته أو مستورداته من السلع والخدمات خلال فترة تسجيله باستثناء المدرج منها في الجدول رقم (٤) الملحق بهذا القانون.\nد- ما سبق له تحمله قبل التسجيل من ضريبة عامة على السلع التي تكون في حوزته عن التسجيل.\nهـ - ما سبق له تحمله من ضريبة خاصة على السلع التي تدخل في إنتاج سلع أخرى خاضعة للضريبة الخاصة.","title":"الخصم من الضريبة المستحقة","memo":"⭐ يخصم المسجل: ضريبة المرتجعات، والضريبة العامة على المبيعات الآجلة التي أصبحت ديوناً معدومة\n⭐ ضريبة المشتريات والمستوردات خلال فترة التسجيل باستثناء المدرج في الجدول (٤)\n⭐ الضريبة المتحملة قبل التسجيل على السلع التي بحوزته عند التسجيل؛ والضريبة الخاصة على مدخلات سلع خاضعة للخاصة","qs":[{"q":"أي مما يلي لا يجوز للمسجل خصمه من الضريبة المستحقة على مبيعاته؟","o":["الضريبة العامة على مشتريات مدرجة في الجدول رقم (٤)","الضريبة على المرتجع من مبيعاته","الضريبة العامة على المبيعات المؤجلة الدفع التي أصبحت ديوناً معدومة","الضريبة العامة المتحملة قبل التسجيل على السلع التي بحوزته عند التسجيل"],"a":0},{"q":"يجوز للمسجل خصم الضريبة الخاصة التي تحملها على السلع:","o":["التي تدخل في إنتاج سلع أخرى خاضعة للضريبة الخاصة","المستعملة لأغراضه الشخصية","المعفاة من الضريبة","المدرجة في الجدول رقم (٤)"],"a":0},{"q":"أصبحت مبيعات آجلة لمسجل في عداد الديون المعدومة، فإنه يحق له خصم:","o":["ما سبق له احتسابه أو دفعه من ضريبة عامة على تلك المبيعات","ضعف الضريبة المدفوعة على تلك المبيعات","الضريبة الخاصة فقط على تلك المبيعات","لا يحق له خصم أي مبلغ"],"a":0}]},{"n":"20","chapter":"","notes":[],"source":"يتم رد الضريبة من مبلغ الضريبة المحصل في السنة نفسها وفق التعليمات التنفيذية الصادرة لهذه الغاية وفي موعد لا يتجاوز (٣٠) يوماً من تاريخ تقديم طلب الرد في أي من الحالات التالية:\nأ- الضريبة التي سبق تحصيلها على السلع او الخدمات المصدرة أو التي استعملت في إنتاج سلع اخرى تم تصديرها.\nب-الضريبة التي تم تحصيلها بطريق الخطأ.\nج- رصيد الضريبة العامة على المدخلات القابلة للخصم بموجب احكام المادة (١٩) من هذا القانون التي مضى على دفعها مدة تجاوزت شهرين ولم يتم خصمها من الضريبة العامة التي استحقت للدائرة خلال تلك المدة.\nد- الضريبة التي تم دفعها على السلع التي تكون بحوزة الأشخاص غير المقيمين عند مغادرتهم المملكة شريطة ألا يقل مقدار الضريبة التي سيتم ردها عن خمسين ديناراً وبحد أعلى خمسمائة دينار.\nهـ- الضريبة الخاصة التي سبق دفعها على السلع المباعة إلى أي من الجهات المعفاة بموجب أحكام المادة (٢١) من هذا القانون وذلك بعد التحقق من استلام الدائرة لهذه الضريبة.","title":"حالات رد الضريبة","memo":"⭐ الرد من حصيلة السنة نفسها خلال مدة لا تتجاوز (٣٠) يوماً من تقديم طلب الرد\n⭐ حالات الرد: الصادرات ومدخلاتها، المحصل خطأً، رصيد المدخلات الذي مضى على دفعه أكثر من شهرين دون خصم\n⭐ غير المقيمين عند المغادرة: لا يقل الرد عن ٥٠ ديناراً وبحد أعلى ٥٠٠ دينار\n⭐ الضريبة الخاصة على السلع المباعة للجهات المعفاة بالمادة (٢١) بعد التحقق من استلام الدائرة لها","qs":[{"q":"يتم رد الضريبة في الحالات المحددة في موعد لا يتجاوز:","o":["(٣٠) يوماً من تاريخ تقديم طلب الرد","(٦٠) يوماً من تاريخ تقديم طلب الرد","(٩٠) يوماً من تاريخ تقديم طلب الرد","نهاية السنة المالية"],"a":0},{"q":"الحد الأدنى والأعلى لمقدار الضريبة التي ترد للأشخاص غير المقيمين عند مغادرتهم المملكة هما:","o":["خمسون ديناراً وخمسمائة دينار","مائة دينار وألف دينار","عشرون ديناراً ومائتا دينار","خمسون ديناراً وألف دينار"],"a":0},{"q":"يحق للمسجل طلب رد رصيد الضريبة العامة على المدخلات القابلة للخصم إذا مضى على دفعها مدة تجاوزت:","o":["شهرين ولم يتم خصمها","شهراً واحداً ولم يتم خصمها","ستة أشهر ولم يتم خصمها","سنة كاملة ولم يتم خصمها"],"a":0}]},{"n":"21","chapter":"","notes":[],"source":"أ- يعفى من الضريبة:\n١- مشتريات ومستوردات جلالة الملك من السلع والخدمات.\n٢- السلع والخدمات التي تستوردها أو تشتريها محليا السفارات والمفوضيات والقنصليات غير الفخرية لاستعمالها الخاص وفقا لتوصيات وزير الخارجية وشريطة المعاملة بالمثل.\n٣- السلع والخدمات التي يستوردها أو يشتريها محلياً أعضاء السلكين الدبلوماسي والقنصلي المعتمدين لدى المملكة شريطة أن يكونوا غير أردنيين وغير فخريين وفقا لتوصيات وزير الخارجية وشريطة المعاملة بالمثل.\n٤- السلع والخدمات التي تستوردها او تشتريها محليا المنظمات الدولية والاقليمية العاملة في المملكة وموظفوها غير الاردنيين الذين يتمتعون بالصفة الدبلوماسية.\nب-يتم تحديد وتنظيم حجم السلع والخدمات المعفاة المنصوص عليها في البنود (٢) و(٣) و(٤) من الفقرة(أ) من هذه المادة بقرار من الوزير بالاتفاق مع وزير الخارجية.","title":"الإعفاءات الدبلوماسية والملكية","memo":"⭐ يعفى: مشتريات ومستوردات جلالة الملك\n⭐ السفارات والقنصليات غير الفخرية، والدبلوماسيون غير الأردنيين وغير الفخريين: بتوصية وزير الخارجية وبشرط المعاملة بالمثل\n⭐ المنظمات الدولية والإقليمية وموظفوها غير الأردنيين ذوو الصفة الدبلوماسية\n⭐ حجم المعفى يحدد بقرار من الوزير بالاتفاق مع وزير الخارجية","qs":[{"q":"يتم تحديد وتنظيم حجم السلع والخدمات المعفاة للسفارات والدبلوماسيين والمنظمات الدولية بقرار من:","o":["الوزير بالاتفاق مع وزير الخارجية","وزير الخارجية منفرداً","مجلس الوزراء بتنسيب المدير","المدير بالاتفاق مع مدير عام الجمارك"],"a":0},{"q":"يشترط لإعفاء مشتريات أعضاء السلك الدبلوماسي المعتمدين لدى المملكة أن يكونوا:","o":["غير أردنيين وغير فخريين وبشرط المعاملة بالمثل","أردنيين أو أجانب دون شرط المعاملة بالمثل","فخريين فقط","مقيمين في المملكة مدة لا تقل عن سنة"],"a":0},{"q":"أي مما يلي لا يشمله الإعفاء بموجب المادة (٢١)؟","o":["مشتريات القنصليات الفخرية","مشتريات ومستوردات جلالة الملك","مستوردات المنظمات الدولية العاملة في المملكة","مشتريات السفارات لاستعمالها الخاص بشرط المعاملة بالمثل"],"a":0}]},{"n":"22","chapter":"","notes":[],"source":"أ- تخضع للضريبة بنسبة أو بمقدار (صفر) السلع والخدمات التي يتم استيرادها أو شراؤها محليا لاستعمال اي من الجهات والمشاريع التالية:\n١- القوات المسلحة والأمن العام والمخابرات العامة والدفاع المدني.\n٢- المساجد والكنائس ومراكز الأيتام والمسنين والأندية الرياضية والثقافية والأشخاص الطبيعيين من ذوي الاحتياجات الخاصة.\n٣- المشاريع التي تتمتع بالإعفاءات المنصوص عليها في قانون تشجيع الاستثمار.\nب-تقوم الدائرة بوضع أسس الرقابة اللازمة لضمان استعمال مستوردات ومشتريات الجهات والمشاريع المنصوص عليها في الفقرة (أ) من هذه المادة في الأغراض المقررة لها.\nج- تعفى من الضريبة أي سلعة او خدمة كما يعفى منها أي شخص عند موافقة مجلس الوزراء على هذا الإعفاء كليا أو جزئيا في حالات محددة ولأسباب مبررة بناء على تنسيب من الوزير.","title":"جهات النسبة الصفرية والإعفاء بقرار","memo":"⭐ (صفر) لمستوردات ومشتريات: القوات المسلحة والأمن العام والمخابرات والدفاع المدني\n⭐ والمساجد والكنائس ومراكز الأيتام والمسنين والأندية الرياضية والثقافية وذوي الاحتياجات الخاصة، ومشاريع قانون تشجيع الاستثمار\n⭐ الدائرة تضع أسس الرقابة على استعمالها\n⭐ الإعفاء الكلي أو الجزئي لأي سلعة أو شخص بموافقة مجلس الوزراء بتنسيب الوزير لأسباب مبررة","qs":[{"q":"تخضع مستوردات ومشتريات القوات المسلحة والأمن العام للضريبة:","o":["بنسبة أو بمقدار (صفر)","بنسبة (%١٦)","بنسبة مخفضة يحددها الوزير","بنسبة (%٨)"],"a":0},{"q":"الجهة المختصة بإعفاء أي سلعة أو خدمة أو أي شخص من الضريبة كلياً أو جزئياً في حالات محددة هي:","o":["مجلس الوزراء بناءً على تنسيب الوزير","الوزير بناءً على تنسيب المدير","المدير","مجلس الأمة"],"a":0},{"q":"الجهة التي تضع أسس الرقابة اللازمة لضمان استعمال مستوردات الجهات المنصوص عليها في الفقرة (أ) في الأغراض المقررة لها هي:","o":["الدائرة","دائرة الجمارك","وزارة الصناعة والتجارة","ديوان المحاسبة"],"a":0}]},{"n":"23","chapter":"","notes":[],"source":"يعفى من الضريبة في الحدود وبالشروط والأوضاع التي تحددها التعليمات التنفيذية ما يلي:\nأ- العينات التي تستهلك في أغراض التحليل بالمختبرات شريطة أن تكون كمياتها في حدود متطلبات التحليل وفق الأصول الفنية المعتمدة.\nب-الأشياء الشخصية المجردة من أية صفة تجارية كالنياشين والميداليات والجوائز الرياضية والعلمية.\nج- المواد التي ترد من خارج المملكة كبدل تالف أو ناقص عن إرساليات سبق توريدها أو رفض قبولها وحصلت الضريبة عليها كاملة في حينها بشرط أن تتحقق دائرة الجمارك من صفتها هذه.\nد- الأمتعة الشخصية الخاصة بالمسافرين القادمين من الخارج، كما يعفى الأثاث المستعمل بالنسبة أو بالشرط المنصوص عليها في قانون الجمارك المعمول به للقادمين للإقامة الدائمة في المملكة.\nهـ- السلع والخدمات التي دفعت الضريبة عليها وصدرت للخارج ولم ترد الضريبة عليها ثم أعيد استيرادها بذاتها خلال المدة المحددة في قانون الجمارك بشرط أن تتحقق دائرة الجمارك من ذلك.","title":"إعفاءات العينات والأمتعة","memo":"⭐ معفاة في حدود وشروط التعليمات التنفيذية: عينات التحليل المخبري، الأشياء الشخصية غير التجارية (نياشين، ميداليات، جوائز)\n⭐ بدل التالف أو الناقص من إرساليات حصلت ضريبتها كاملة بتحقق دائرة الجمارك\n⭐ الأمتعة الشخصية للقادمين، والأثاث المستعمل للقادمين للإقامة الدائمة وفق قانون الجمارك\n⭐ السلع المصدرة التي لم ترد ضريبتها وأعيد استيرادها بذاتها خلال مدة قانون الجمارك","qs":[{"q":"تحدد حدود وشروط الإعفاءات الواردة في المادة (٢٣) بموجب:","o":["التعليمات التنفيذية","نظام يصدره مجلس الوزراء","قرار من وزير الخارجية","قانون تشجيع الاستثمار"],"a":0},{"q":"أي مما يلي يعفى من الضريبة بموجب المادة (٢٣)؟","o":["الميداليات والجوائز الرياضية المجردة من أية صفة تجارية","العينات التجارية المعدة للبيع","الأثاث الجديد المستورد لغايات تجارية","السلع المصدرة التي ردت ضريبتها ثم أعيد استيرادها"],"a":0},{"q":"يشترط لإعفاء المواد الواردة كبدل تالف عن إرساليات سابقة أن:","o":["تكون الضريبة قد حصلت عليها كاملة وتتحقق دائرة الجمارك من صفتها","تكون الإرسالية الأصلية معفاة من الضريبة","يوافق مجلس الوزراء على الإعفاء","لا تتجاوز قيمتها خمسمائة دينار"],"a":0}]},{"n":"24","chapter":"","notes":[],"source":"على الرغم مما ورد في القوانين الأخرى من إعفاءات ضريبية لا تسري الإعفاءات على هذه الضريبة إلا ما نص عليه في هذا القانون.","title":"حصر الإعفاءات بالقانون","memo":"⭐ لا تسري الإعفاءات الضريبية الواردة في القوانين الأخرى على ضريبة المبيعات إلا ما نص عليه في هذا القانون","qs":[{"q":"نص قانون آخر على إعفاء جهة من الضرائب بشكل عام، فإن هذا الإعفاء بالنسبة لضريبة المبيعات:","o":["لا يسري إلا إذا نص عليه قانون الضريبة العامة على المبيعات","يسري تلقائياً","يسري بقرار من المدير","يسري بنسبة (%٥٠) فقط"],"a":0}]},{"n":"25","chapter":"","notes":[],"source":"أ-\n١- يلتزم الشخص الذي تصرف في أي من السلع المعفاة من دفع الضريبة أو استعملها خلال الخمس سنوات التالية للإعفاء في غير الغاية التي أعفيت من أجلها بتسديد الضريبة المستحقة عليها وفقا لقيمة السلعة وفئة الضريبة بتاريخ التصرف أو الاستعمال.\n٢- إذا لم تسدد الضريبة وفقا للبند (١) من هذه الفقرة، فتستوفى الضريبة وأي مبالغ مستحقة عليها على أساس تاريخ التصرف أو الاستعمال أو تاريخ اكتشاف الفعل أو تاريخ التسوية الصلحية وفقا للضريبة الأعلى أي من هذه الحالات.\nب-على الرغم مما ورد في الفقرة (أ) من هذه المادة تحتسب الضريبة على السيارات المعفاة إذا تم التصرف بها وفقا للقيمة المحددة من قبل دائرة الجمارك.","title":"التصرف في السلع المعفاة","memo":"⭐ التصرف أو الاستعمال في غير غاية الإعفاء خلال الخمس سنوات التالية: تسدد الضريبة وفق القيمة والفئة بتاريخ التصرف أو الاستعمال\n⭐ إذا لم تسدد: تستوفى على أساس الأعلى من تاريخ التصرف أو تاريخ الاكتشاف أو تاريخ التسوية الصلحية\n⭐ السيارات المعفاة: تحتسب الضريبة وفق القيمة المحددة من دائرة الجمارك","qs":[{"q":"يلتزم الشخص بتسديد الضريبة إذا تصرف في السلع المعفاة في غير الغاية التي أعفيت من أجلها خلال:","o":["الخمس سنوات التالية للإعفاء","الثلاث سنوات التالية للإعفاء","السنتين التاليتين للإعفاء","العشر سنوات التالية للإعفاء"],"a":0},{"q":"تحتسب الضريبة على السيارات المعفاة إذا تم التصرف بها وفقاً:","o":["للقيمة المحددة من قبل دائرة الجمارك","لسعر الشراء الأصلي","لسعر السوق الذي يقدره المدقق","لقيمة الفاتورة الضريبية الأولى"],"a":0},{"q":"تصرف شخص في سلعة معفاة خلافاً لغاية الإعفاء ولم يسدد الضريبة، فإنها تستوفى على أساس:","o":["الضريبة الأعلى من بين تاريخ التصرف أو تاريخ اكتشاف الفعل أو تاريخ التسوية الصلحية","تاريخ الإعفاء الأصلي","الضريبة الأدنى من بين تاريخ التصرف وتاريخ الاكتشاف","تاريخ صدور الحكم القطعي فقط"],"a":0}]},{"n":"26","chapter":"","notes":[],"source":"أ- على المسجل دفع رصيد الضريبة دورياً للدائرة وفق إقراره أو الإقرار المعدل وذلك في الموعد المحدد بموجب أحكام هذا القانون.\nب-على مستورد السلعة دفع الضريبة المستحقة عليها عند الإفراج عن السلعة من دائرة الجمارك وفقا للإجراءات المقررة لدفع الرسوم الجمركية، ولا يجوز التخليص عليها قبل تسديد الضريبة المستحقة عليها بكاملها.\nج- على مستورد الخدمة دفع الضريبة المستحقة عليه للدائرة في أي من الحالات التالية أيها أسبق:\n١- خلال شهر واحد من تاريخ دفع بدل الخدمة المستوردة أو أي جزء منه وذلك بحدود ما يتعلق بذلك الجزء.\n٢- عند إفراج السلطات الجمركية عن المادة التي قدمت بواسطتها تلك الخدمة.\n٣- خلال ستة أشهر من تاريخ تلقي الخدمة أو أي جزء منها وذلك بحدود ما يتعلق بذلك الجزء.\nد- على الرغم مما ورد في الفقرتين (ب) و(ج) من هذه المادة إذا كان المستورد مسجلاً فيجوز بموافقة المدير تأجيل دفع الضريبة المترتبة على استيراد السلعة أو الخدمة وفق الشروط والإجراءات التي تحددها التعليمات التنفيذية الصادرة لهذه الغاية.","title":"مواعيد دفع الضريبة","memo":"⭐ المسجل يدفع رصيد الضريبة دورياً وفق إقراره في الموعد المحدد\n⭐ مستورد السلعة يدفع عند الإفراج الجمركي ولا يجوز التخليص قبل تسديدها كاملة\n⭐ مستورد الخدمة يدفع عند الأسبق: خلال شهر من دفع البدل، أو عند الإفراج الجمركي عن المادة الحاملة، أو خلال ستة أشهر من تلقي الخدمة\n⭐ يجوز للمستورد المسجل تأجيل الدفع بموافقة المدير","qs":[{"q":"يلتزم مستورد الخدمة بدفع الضريبة خلال شهر واحد من تاريخ دفع بدل الخدمة، أو خلال مدة من تاريخ تلقي الخدمة مقدارها:","o":["ستة أشهر","ثلاثة أشهر","شهران","سنة واحدة"],"a":0},{"q":"يجوز تأجيل دفع الضريبة المترتبة على استيراد السلعة أو الخدمة إذا كان المستورد:","o":["مسجلاً وبموافقة المدير","غير مسجل وبموافقة الوزير","جهة حكومية فقط","مقيماً في منطقة حرة"],"a":0},{"q":"بالنسبة لمستورد السلعة، فإنه:","o":["لا يجوز التخليص على السلعة قبل تسديد الضريبة المستحقة عليها بكاملها","يجوز التخليص على السلعة ودفع الضريبة خلال شهر","يجوز التخليص بعد دفع نصف الضريبة","يدفع الضريبة مع إقراره الدوري فقط"],"a":0}]},{"n":"27","chapter":"","notes":[],"source":"تكون الرقابة غير مباشرة دفترية أو آلية، وللوزير فرض الرقابة المباشرة إذا رأى ضرورة لذلك على أن يحدد بتعليمات تنفيذية شكل الرقابة وحدودها على المصانع والمحال التجارية وغيرها من الأماكن التي يتم فيها مزاولة أعمال خاضعة للضريبة حسب الظروف والاعتبارات التي يقدرها.","title":"أنواع الرقابة","memo":"⭐ الأصل: رقابة غير مباشرة دفترية أو آلية\n⭐ للوزير فرض الرقابة المباشرة إذا رأى ضرورة، ويحدد شكلها وحدودها بتعليمات تنفيذية","qs":[{"q":"الأصل في الرقابة وفق قانون الضريبة العامة على المبيعات أن تكون:","o":["غير مباشرة دفترية أو آلية","مباشرة دائمة على المصانع","مباشرة بقرار من المدير","ميدانية فقط"],"a":0},{"q":"الجهة التي تملك فرض الرقابة المباشرة على الأماكن التي تزاول فيها أعمال خاضعة للضريبة هي:","o":["الوزير","المدير","مجلس الوزراء","المدقق"],"a":0}]},{"n":"28","chapter":"","notes":[],"source":"باستثناء الحالات التي تعتبر من أعمال التهرب من الضريبة المنصوص عليها في هذا القانون، للمدير أن يفرض غرامة لا تقل عن مائة دينار ولا تتجاوز خمسمائة دينار على كل من يرتكب أي من المخالفات التالية:\nأ- التخلف عن تقديم طلب التسجيل لدى الدائرة مدة لا تزيد على ستين يوما من تاريخ انقضاء المدة المحددة للتسجيل بموجب احكام المادة (١٣) من هذه القانون.\nب-التخلف عن تقديم الإقرار الضريبي ضمن المواعيد المحددة في هذا القانون.\nج- تقديم إقرار بالمبيعات من السلع أو الخدمات الخاضعة للضريبة إذا ظهر نقص في قيمة المبيعات الحقيقية الخاضعة للضريبة لا تزيد نسبته على (%١٠) أو خمسة الاف دينار أيهما أقل.\nد- مخالفة أحكام المادة (١٨) من هذا القانون إذا أدت هذه المخالفة إلى نقص في مقدار الضريبة المصرح عنها أو المستحقة.\nه- عدم إعلام الدائرة بالتغييرات التي طرأت على البيانات الواردة في طلب التسجيل خلال الموعد المحدد.\nو- عدم الاستجابة دون عذر مبرر لأي من مذكرات الحضور أو الإشعارات أو الطلبات الصادرة خطيا عن موظفي الدائرة أثناء قيامهم بواجباتهم أو مسؤولياتهم وفق أحكام هذا القانون.\nز- التصرف في أي من السلع المعفاة من الضريبة أو استعمالها في غير الغرض الذي أعفيت من أجله بصورة مخالفة لأحكام المادة (٢٥) من هذا القانون إذا أدى ذلك الى نقص لا يتجاوز خمسماية دينار في مقدار الضريبة المستحقة.\nح- تطبيق نسب أو فئات ضريبية على السلع أو الخدمات الخاضعة للضريبة بصورة مخالفة لأحكام هذا القانون إذا ادى ذلك إلى نقص في مقدار الضريبة المستحقة لا يتجاوز خمسماية دينار.\nط- خصم الضريبة أو ردها بصورة مخالفة لأحكام هذا القانون إذا ظهر زيادة في مقدار الخصم أو الرد لا تتجاوز قيمتها خمسماية دينار.\nي- خصم الضريبة أو ردها عن سلع تم الاستفادة منها أو استعمالها في إنتاج سلع أخرى لأغراض شخصية وذلك إذا كان مقدار هذا الخصم أو الرد لا يزيد على خمسماية دينار.\nك- تقديم مستندات أو وثائق أو بيانات غير صحيحة أو إصدار أي منها إذا أدى ذلك إلى نقص في مقدار الضريبة المصرح عنها أو المستحقة لا يتجاوز قيمتها خمسماية دينار.\nل- عدم تمكين موظفي الدائرة من القيام بواجباتهم أو ممارسة صلاحياتهم في الرقابة والتفتيش وفق أحكام هذا القانون.","title":"المخالفات وغراماتها","memo":"⭐ للمدير فرض غرامة من ١٠٠ إلى ٥٠٠ دينار على المخالفات (غير التهرب)\n⭐ التخلف عن التسجيل مدة لا تزيد على ٦٠ يوماً؛ عدم تقديم الإقرار في موعده\n⭐ نقص المبيعات المصرح عنها بنسبة لا تزيد على (%١٠) أو ٥٠٠٠ دينار أيهما أقل\n⭐ نقص الضريبة أو زيادة الخصم أو الرد بما لا يتجاوز ٥٠٠ دينار في حالات محددة","qs":[{"q":"الغرامة التي يفرضها المدير على المخالفات المنصوص عليها في المادة (٢٨):","o":["لا تقل عن مائة دينار ولا تتجاوز خمسمائة دينار","لا تقل عن مائتي دينار ولا تتجاوز ألف دينار","لا تقل عن خمسين ديناراً ولا تتجاوز خمسمائة دينار","لا تقل عن مائة دينار ولا تتجاوز ألف دينار"],"a":0},{"q":"تخلف شخص عن تقديم طلب التسجيل مدة (٤٥) يوماً من تاريخ انقضاء المدة المحددة للتسجيل، فإن فعله يعد:","o":["مخالفة يفرض عليها المدير غرامة","تهرباً من الضريبة","فعلاً غير معاقب عليه","جريمة عقوبتها الحبس"],"a":0},{"q":"يعد مخالفة (لا تهرباً) تقديم إقرار يظهر نقص في قيمة المبيعات الحقيقية الخاضعة للضريبة لا تزيد نسبته على:","o":["(%١٠) أو خمسة آلاف دينار أيهما أقل","(%١٠) أو خمسة آلاف دينار أيهما أعلى","(%٢٠) أو عشرة آلاف دينار أيهما أقل","(%٥) أو ألف دينار أيهما أقل"],"a":0}]},{"n":"29","chapter":"","notes":[],"source":"أ- يبلغ المخالف وفق الإجراءات المنصوص عليها في هذا القانون بالغرامة المفروضة عليه وعلى المخالف دفع الغرامة خلال ثلاثين يوما من تاريخ تبلغه بها.\nب-يجوز الاعتراض لدى الوزير على قرارات التغريم الصادرة بمقتضى أحكام المادة (٢٨) من هذا القانون خلال المدة المحددة في الفقرة (أ) من هذه المادة وللوزير إلغاء أو تخفيض أو تثبيت الغرامة إذا تبين له ما يبرر ذلك.\nج- يكون قرار الوزير الذي يصدر بموجب الفقرة (ب) من هذه المادة قابلا للطعن لدى المحكمة المختصة خلال ثلاثين يوما من تاريخ تبليغه وللمحكمة أن تؤيد الغرامة أو تعدلها أو تلغيها.\nد- للمدير أو من يفوضه إجراء المصالحة على المخالفات المنصوص عليها في المادة (٢٨) من هذا القانون مقابل دفع الضريبة في حال استحقاقها وغرامة لا تقل عن نصف الحد الأدنى ولا تزيد على نصف الحد الأعلى من الغرامات المنصوص عليها في المادة (٢٨) من هذا القانون وذلك قبل صدور حكم قطعي من المحكمة ويترتب على المصالحة وقف السير بإجراءات الدعوى وإسقاطها نهائيا وإلغاء ما قد يترتب على ذلك من آثار.","title":"الاعتراض على الغرامة والمصالحة","memo":"⭐ دفع الغرامة خلال ٣٠ يوماً من التبلغ؛ الاعتراض لدى الوزير خلال المدة نفسها (له إلغاؤها أو تخفيضها أو تثبيتها)\n⭐ الطعن بقرار الوزير لدى المحكمة المختصة خلال ٣٠ يوماً من تبليغه\n⭐ للمدير أو من يفوضه المصالحة قبل الحكم القطعي مقابل الضريبة وغرامة بين نصف الحد الأدنى ونصف الحد الأعلى\n⭐ المصالحة توقف إجراءات الدعوى وتسقطها نهائياً","qs":[{"q":"يجوز الاعتراض على قرارات التغريم الصادرة بمقتضى المادة (٢٨) لدى:","o":["الوزير","المدير","هيئة الاعتراض","مجلس الوزراء"],"a":0},{"q":"الغرامة في المصالحة على المخالفات المنصوص عليها في المادة (٢٨) تكون:","o":["لا تقل عن نصف الحد الأدنى ولا تزيد على نصف الحد الأعلى","لا تقل عن الحد الأدنى ولا تزيد على الحد الأعلى","مثل الضريبة المستحقة","ضعف الحد الأدنى"],"a":0},{"q":"بحساب نصف الحدين المنصوص عليهما في المادة (٢٨)، فإن غرامة المصالحة على المخالفة تتراوح بين:","o":["خمسين ديناراً ومائتين وخمسين ديناراً","مائة دينار وخمسمائة دينار","خمسة وعشرين ديناراً ومائتين وخمسين ديناراً","مائتي دينار وألف دينار"],"a":0},{"q":"يكون قرار الوزير بشأن الاعتراض على الغرامة قابلاً للطعن لدى المحكمة المختصة خلال:","o":["ثلاثين يوماً من تاريخ تبليغه","ستين يوماً من تاريخ تبليغه","خمسة عشر يوماً من تاريخ تبليغه","تسعين يوماً من تاريخ صدوره"],"a":0}]},{"n":"30","chapter":"","notes":[],"source":"يعد تهربا من الضريبة ارتكاب أي من الافعال التالية:\nأ- التخلف عن تقديم طلب التسجيل لدى الدائرة مدة تزيد على ستين يوما من تاريخ انقضاء المدة المحددة للتسجيل بموجب احكام المادة (١٣) من هذا القانون.\nب-إلغاء تسجيل المكلف بناء على طلبه إذا ثبت أنه ما زال ملزما بالتسجيل وفق أحكام هذا القانون.\nج- تقديم إقرار بالمبيعات من السلع أو الخدمات الخاضعة للضريبة إذا ظهر نقص في قيمة المبيعات الحقيقية الخاضعة للضريبة تتجاوز نسبته (%١٠) أو خمسة آلاف دينار أيهما أقل.\nد- استيفاء أي شخص ضريبة غير مستحقة إلا إذا تم توريدها للدائرة خلال المدة التي يحددها القانون لتوريد الضريبة أو يتم توريدها قبل اكتشافها.\nه- التصرف في أي من السلع المعفاة من الضريبة أو استعمالها في غير الغرض الذي أعفيت من أجله بصورة مخالفة لأحكام المادة (٢٥) من هذا القانون إذا ادى ذلك الى نقص يتجاوز خمسمائة دينار في مقدار الضريبة المستحقة.\nو- تطبيق نسب أو فئات ضريبية على السلع أو الخدمات الخاضعة للضريبة بصورة مخالفة لأحكام هذا القانون إذا أدى ذلك الى نقص في مقدار الضريبة المستحقة يتجاوز قيمته خمسمائة دينار.\nز- خصم الضريبة أو ردها بصورة مخالفة لأحكام هذا القانون إذا ظهرت زيادة في الخصم أو الرد تتجاوز قيمتها خمسمائة دينار.\nح- خصم الضريبة أو ردها عن سلع تم الاستفادة منها أو استعمالها في إنتاج سلع أخرى لأغراض شخصية وذلك إذا كان مقدار هذا الخصم أو الرد يتجاوز قيمته خمسمائة دينار.\nط- تقديم أو إصدار مستندات أو وثائق أو بيانات غير صحيحة أو الامتناع عن تقديم أو إصدار المستندات أو الوثائق المطلوبة بموجب أحكام هذا القانون أو تأجيل تقديمها أو اصدارها بقصد التهرب الضريبي إذا أدى ذلك إلى نقص في مقدار الضريبة المصرح عنها أو المستحقة تتجاوز قيمته خمسمائة دينار.\nي- تقديم مستندات مزورة أو مصطنعة أو إصدار أي منها بقصد تخفيض الضريبة أو خصمها أو ردها خلافا لأحكام هذا القانون.\nك- حيازة السلع الخاضعة للضريبة بقصد الإتجار بها مع علمه بأنها مهربة من الضريبة.\nل- التخلف عن دفع الضريبة المستحقة على بدل الخدمة المستوردة لمدة تزيد على ثلاثة أشهر من التاريخ المحدد لدفعها بموجب أحكام هذا القانون.","title":"أفعال التهرب الضريبي","memo":"⭐ التخلف عن التسجيل أكثر من ٦٠ يوماً؛ إلغاء التسجيل بطلب المكلف مع بقاء التزامه\n⭐ نقص المبيعات المصرح عنها بنسبة تتجاوز (%١٠) أو ٥٠٠٠ دينار أيهما أقل؛ النقص أو الزيادة بما يتجاوز ٥٠٠ دينار\n⭐ استيفاء ضريبة غير مستحقة ما لم تورد؛ المستندات المزورة؛ حيازة سلع مهربة بقصد الإتجار مع العلم\n⭐ التخلف عن دفع ضريبة الخدمة المستوردة أكثر من ثلاثة أشهر من التاريخ المحدد","qs":[{"q":"يعد تهرباً من الضريبة التخلف عن تقديم طلب التسجيل مدة تزيد على:","o":["ستين يوماً من تاريخ انقضاء المدة المحددة للتسجيل","ثلاثين يوماً من تاريخ انقضاء المدة المحددة للتسجيل","تسعين يوماً من تاريخ أول بيع","ستة أشهر من تاريخ بدء العمل"],"a":0},{"q":"يعد تهرباً التخلف عن دفع الضريبة المستحقة على بدل الخدمة المستوردة لمدة تزيد على:","o":["ثلاثة أشهر من التاريخ المحدد لدفعها","شهر واحد من التاريخ المحدد لدفعها","ستة أشهر من التاريخ المحدد لدفعها","سنة من التاريخ المحدد لدفعها"],"a":0},{"q":"استوفى شخص ضريبة غير مستحقة من عملائه، فإن فعله لا يعد تهرباً إذا:","o":["تم توريدها للدائرة خلال المدة المحددة قانوناً أو قبل اكتشافها","كان المبلغ أقل من خمسمائة دينار","أعادها للعملاء بعد اكتشافها","كان غير مسجل لدى الدائرة"],"a":0},{"q":"خصم مسجل ضريبة بصورة مخالفة للقانون فظهرت زيادة في الخصم قيمتها (٨٠٠) دينار، فإن فعله يعد:","o":["تهرباً من الضريبة","مخالفة يفرض عليها المدير غرامة من ١٠٠ إلى ٥٠٠ دينار","فعلاً غير معاقب عليه","خطأً إدارياً يصحح بإقرار معدل دون عقوبة"],"a":0}]},{"n":"31","chapter":"","notes":[],"source":"يعاقب كل من يرتكب جرم التهرب من الضريبة بدفع تعويض مدني للدائرة لا يقل عن مثلي مقدار الضريبة ولا يزيد على ثلاثة أمثالها، وبغرامة جزائية لا تقل عن مئتي دينار ولا تزيد على ألف دينار، وفي حالة التكرار للمرة الثانية تضاعف الغرامة الجزائية المحكوم بها، وإذا تكرر ارتكاب الجرم بعد ذلك خلال سنة واحدة فللمحكمة أن تحكم بالحد الأعلى للغرامة أو بالحبس لمدة لا تقل عن ثلاثة أشهر ولا تزيد على ستة أشهر أو بكلتا العقوبتين.","title":"عقوبة التهرب الضريبي","memo":"⭐ تعويض مدني لا يقل عن مثلي الضريبة ولا يزيد على ثلاثة أمثالها\n⭐ غرامة جزائية من ٢٠٠ إلى ١٠٠٠ دينار، تضاعف عند التكرار للمرة الثانية\n⭐ التكرار بعد ذلك خلال سنة: الحد الأعلى للغرامة أو الحبس من ٣ إلى ٦ أشهر أو كلتاهما","qs":[{"q":"التعويض المدني الذي يدفعه مرتكب جرم التهرب للدائرة:","o":["لا يقل عن مثلي مقدار الضريبة ولا يزيد على ثلاثة أمثالها","لا يقل عن مثل الضريبة ولا يزيد على مثليها","يعادل ثلاثة أمثال الضريبة دائماً","لا يقل عن ثلاثة أمثال الضريبة ولا يزيد على خمسة أمثالها"],"a":0},{"q":"الغرامة الجزائية لجرم التهرب من الضريبة:","o":["لا تقل عن مئتي دينار ولا تزيد على ألف دينار","لا تقل عن مائة دينار ولا تزيد على خمسمائة دينار","لا تقل عن خمسمائة دينار ولا تزيد على ألفي دينار","لا تقل عن ألف دينار ولا تزيد على خمسة آلاف دينار"],"a":0},{"q":"تكرر ارتكاب جرم التهرب بعد المرة الثانية خلال سنة واحدة، فللمحكمة أن تحكم بالحد الأعلى للغرامة أو بالحبس مدة:","o":["لا تقل عن ثلاثة أشهر ولا تزيد على ستة أشهر","لا تقل عن شهر ولا تزيد على ثلاثة أشهر","لا تقل عن ستة أشهر ولا تزيد على سنة","لا تقل عن سنة ولا تزيد على ثلاث سنوات"],"a":0}]},{"n":"32","chapter":"","notes":[],"source":"للوزير أو من يفوضه عقد المصالحة في جرائم التهرب من الضريبة وذلك قبل صدور حكم قطعي في الدعوى مقابل دفع الضريبة موضوع القضية وغرامة بمثابة تعويض مدني يعادل مثل الضريبة، ويترتب على المصالحة سقوط الدعوى الجزائية ووقف السير بإجراءاتها وإلغاء ما يترتب على ذلك من آثار.","title":"المصالحة في جرائم التهرب","memo":"⭐ للوزير أو من يفوضه المصالحة قبل صدور حكم قطعي\n⭐ مقابل دفع الضريبة وغرامة بمثابة تعويض مدني يعادل مثل الضريبة\n⭐ يترتب عليها سقوط الدعوى الجزائية ووقف إجراءاتها وإلغاء آثارها","qs":[{"q":"الجهة المختصة بعقد المصالحة في جرائم التهرب من الضريبة هي:","o":["الوزير أو من يفوضه","المدير أو من يفوضه","المحكمة المختصة","هيئة الاعتراض"],"a":0},{"q":"تتم المصالحة في جرائم التهرب مقابل دفع الضريبة وغرامة بمثابة تعويض مدني يعادل:","o":["مثل الضريبة","مثلي الضريبة","ثلاثة أمثال الضريبة","نصف الضريبة"],"a":0},{"q":"يجوز إجراء المصالحة في جرائم التهرب من الضريبة:","o":["قبل صدور حكم قطعي في الدعوى","بعد صدور الحكم القطعي فقط","خلال ثلاثين يوماً من صدور الحكم القطعي","في أي وقت ولو بعد تنفيذ العقوبة"],"a":0}]},{"n":"33","chapter":"","notes":[],"source":"ينشأ صندوق في الدائرة تحول إليه نسبه لا تزيد عن (%٢٠) من حصيلة الغرامات، لغايات تحسين ظروف العمل ورفع كفاءة موظفي الدائرة وتقديم الخدمات لهم في المجالات الصحية والثقافية والاجتماعية والإسكان وتقديم الحوافز التشجيعية لهم، تصرف أو توزع على الموظفين المتميزين في أدائهم وعلى كل من ساهم في اكتشاف التهرب من الضريبة أو ضبط السلع المهربة منها ويتم ذلك بموجب نظام يصدر لهذه الغاية.","title":"صندوق الدائرة","memo":"⭐ ينشأ صندوق في الدائرة تحول إليه نسبة لا تزيد على (%٢٠) من حصيلة الغرامات\n⭐ غايته تحسين ظروف العمل وحوافز الموظفين المتميزين ومن ساهم في اكتشاف التهرب، ويصدر بشأنه نظام","qs":[{"q":"يحول إلى الصندوق المنشأ في الدائرة نسبة لا تزيد عن:","o":["(%٢٠) من حصيلة الغرامات","(%١٠) من حصيلة الغرامات","(%٢٥) من حصيلة الضريبة","(%٥) من حصيلة الضريبة"],"a":0},{"q":"تنظم أحكام صرف وتوزيع أموال صندوق الدائرة بموجب:","o":["نظام يصدر لهذه الغاية","تعليمات يصدرها المدير","قرار من الوزير","التعليمات التنفيذية"],"a":0}]},{"n":"34","chapter":"","notes":[],"source":"يحدد الوزير بتعليمات يصدرها المبالغ التي يجب استيفاؤها من المكلفين مقابل المطبوعات وطوابع البندرول والعلامات المميزة ومصاريف التحليل.","title":"رسوم المطبوعات والبندرول","memo":"⭐ يحدد الوزير بتعليمات المبالغ المستوفاة مقابل المطبوعات وطوابع البندرول والعلامات المميزة ومصاريف التحليل","qs":[{"q":"يحدد المبالغ الواجب استيفاؤها من المكلفين مقابل المطبوعات وطوابع البندرول ومصاريف التحليل:","o":["الوزير بتعليمات يصدرها","المدير بقرار منه","مجلس الوزراء بنظام","دائرة الجمارك"],"a":0}]},{"n":"35","chapter":"","notes":[],"source":"يتم ضمان دفع الضريبة المستحقة على السلع التي يوافق مدير عام الجمارك على إدخالها إدخالا مؤقتا بموجب كفالة بنكية أو بأي ضمانات أخرى يقبلها إلى حين زوال صفة الإدخال المؤقت وذلك وفق الشروط والإجراءات التي تحددها التعليمات التنفيذية.","title":"ضمان ضريبة الإدخال المؤقت","memo":"⭐ السلع التي يوافق مدير عام الجمارك على إدخالها مؤقتاً تضمن ضريبتها بكفالة بنكية أو ضمانات أخرى يقبلها\n⭐ حتى زوال صفة الإدخال المؤقت وفق التعليمات التنفيذية","qs":[{"q":"يتم ضمان دفع الضريبة المستحقة على السلع المدخلة إدخالاً مؤقتاً بموجب:","o":["كفالة بنكية أو أي ضمانات أخرى يقبلها مدير عام الجمارك","إيداع نقدي لدى وزارة المالية فقط","تعهد خطي من المستورد فقط","رهن عقاري لصالح الدائرة"],"a":0},{"q":"الجهة التي توافق على إدخال السلع إدخالاً مؤقتاً وفق المادة (٣٥) هي:","o":["مدير عام الجمارك","مدير عام دائرة ضريبة الدخل والمبيعات","الوزير","وزير الصناعة والتجارة"],"a":0}]},{"n":"36","chapter":"","notes":[],"source":"أ- تقوم وزارة الصناعة والتجارة بتزويد الدائرة بنسخة من التسجيلات الصناعية والخدمية التي تصدر عن الوزارة التي يرغب منشئوها بإنتاج سلع أو تقديم خدمات.\nب-يترتب على كل منتج لأي سلعة أو مقدم لأي خدمة تزويد الدائرة بنسخة من الترخيص المعطى له خلال ثلاثين يوما من تاريخ حصوله على الترخيص مع بيان وصف للسلعة التي سينتجها أو الخدمة التي سيقدمها.\nج- على منتج أي سلعة أو مقدم أي خدمة إعلام الدائرة عن فترات التوقف الكلي أو الجزئي لعمله وذلك خلال أسبوع من التوقف.","title":"تزويد الدائرة بالتراخيص","memo":"⭐ وزارة الصناعة والتجارة تزود الدائرة بنسخة من التسجيلات الصناعية والخدمية\n⭐ المنتج أو مقدم الخدمة يزود الدائرة بنسخة الترخيص خلال ثلاثين يوماً من حصوله عليه مع وصف للسلعة/الخدمة\n⭐ إعلام الدائرة بفترات التوقف الكلي أو الجزئي خلال أسبوع من التوقف","qs":[{"q":"يلتزم منتج السلعة أو مقدم الخدمة بتزويد الدائرة بنسخة من الترخيص المعطى له خلال:","o":["ثلاثين يوماً من تاريخ حصوله على الترخيص","أسبوع من تاريخ حصوله على الترخيص","ستين يوماً من تاريخ حصوله على الترخيص","تسعين يوماً من تاريخ بدء الإنتاج"],"a":0},{"q":"توقف منتج سلعة عن العمل توقفاً جزئياً، فعليه إعلام الدائرة خلال:","o":["أسبوع من التوقف","ثلاثين يوماً من التوقف","نهاية الفترة الضريبية","ستين يوماً من التوقف"],"a":0},{"q":"الجهة التي تزود الدائرة بنسخة من التسجيلات الصناعية والخدمية هي:","o":["وزارة الصناعة والتجارة","دائرة الجمارك","وزارة العمل","غرفة التجارة"],"a":0}]},{"n":"37","chapter":"","notes":[],"source":"أ- تتولى الدائرة تنفيذ أحكام هذا القانون.\nب-لغايات هذا القانون يعتبر المدير مدققاً كما يمارس الصلاحيات التالية:\n١- تأليف لجنة أو أكثر من المدققين للقيام بأعمال التدقيق أو التقدير وللبت في أي مسائل يحيلها اليها المدير إذا رأى أن مصلحة العمل تقتضي ذلك وتصدر اللجنة قرارها بالإجماع أو بالأكثرية وإذا كانت اللجنة مؤلفة من اثنين واختلفا في الرأي يعين المدير عضوا ثالثا فيها ويعتبر القرار الصادر عن اللجنة قرارا صادرا عن المدقق بمقتضى أحكام هذا القانون.\n٢- اعتماد نماذج الإقرارات الضريبية والإشعارات والمذكرات وأي نماذج أخرى يراها ضرورية لتنفيذ أحكام هذا القانون.\n٣- اتخاذ ما يراه مناسبا من قرارات وإجراءات لتنفيذ أحكام هذا القانون والأنظمة والتعليمات التنفيذية الصادرة بمقتضاه.","title":"صلاحيات الدائرة والمدير","memo":"⭐ تتولى الدائرة تنفيذ أحكام القانون؛ ويعتبر المدير مدققاً\n⭐ للمدير تأليف لجنة أو أكثر من المدققين، وتصدر قرارها بالإجماع أو بالأكثرية\n⭐ إذا كانت اللجنة من اثنين واختلفا يعين المدير عضواً ثالثاً، وقرارها يعتبر قراراً صادراً عن المدقق\n⭐ للمدير اعتماد نماذج الإقرارات والإشعارات والمذكرات","qs":[{"q":"لجنة مدققين مؤلفة من عضوين اختلفا في الرأي، فإن الإجراء وفق القانون:","o":["يعين المدير عضواً ثالثاً فيها","يرجح رأي العضو الأقدم","تحال المسألة إلى هيئة الاعتراض","يحسم الوزير الخلاف"],"a":0},{"q":"يعتبر القرار الصادر عن لجنة المدققين التي يؤلفها المدير:","o":["قراراً صادراً عن المدقق","قراراً صادراً عن الوزير","قراراً قطعياً غير قابل للاعتراض","قراراً صادراً عن هيئة الاعتراض"],"a":0},{"q":"الجهة التي تعتمد نماذج الإقرارات الضريبية والإشعارات والمذكرات هي:","o":["المدير","الوزير","مجلس الوزراء","هيئة الاعتراض"],"a":0}]},{"n":"38","chapter":"","notes":[],"source":"أ- يلتزم المكلف بتنظيم السجلات والمستندات اللازمة لتحديد مقدار الضريبة المستحقة عليه شريطة أن تكون معدة وفق معايير المحاسبة الدولية ومدققة ومصادق عليها من محاسب قانوني ويلزم بالاحتفاظ بها لمدة أربع سنوات تبدأ من آخر أي من التواريخ التالية:\n١- تاريخ انتهاء الفترة الضريبية التي تم تنظيم السجلات والمستندات فيها.\n٢- تاريخ تقديم الإقرار الضريبي.\n٣- تاريخ تبليغ الإشعار بنتيجة قرار التقدير الإداري.\nب-دون الاخلال بأحكام الفقرة (أ) من هذه المادة يلتزم المكلف في حال وجود نزاع على مقدار الضريبة المستحقة أو على أي غرامات ومبالغ متعلقة بها بالاحتفاظ بالسجلات والمستندات إلى حين البت في النزاع او صدور قرار قطعي من المحكمة.\nج- يجوز للمكلف أن ينظم ويمسك سجلاته ومستنداته باللغة الإنجليزية على أن يقدم ترجمة عربية لها إذا طلبت الدائرة ذلك.\nد- يتم إصدار تعليمات تنفيذية لاستثناء فئات معينة من المكلفين من تنظيم السجلات والمستندات كلياً أو جزئياً وفق الشروط والإجراءات المحددة فيها.\nهـ- في حال عدم تنظيم المكلف للسجلات والمستندات وفق الأصول تحدد التعليمات التنفيذية نسب القيم المضافة على المشتريات والمستوردات وتعتبر هذه النسب قرينة قانونية.","title":"السجلات والمستندات","memo":"⭐ السجلات وفق معايير المحاسبة الدولية ومدققة ومصادق عليها من محاسب قانوني\n⭐ الاحتفاظ بها أربع سنوات تبدأ من آخر: انتهاء الفترة الضريبية، تقديم الإقرار، تبليغ إشعار التقدير الإداري\n⭐ عند النزاع: الاحتفاظ إلى حين البت فيه أو صدور قرار قطعي\n⭐ يجوز مسكها بالإنجليزية مع ترجمة عربية عند طلب الدائرة؛ عدم التنظيم: نسب قيم مضافة تعتبر قرينة قانونية","qs":[{"q":"يلتزم المكلف بالاحتفاظ بالسجلات والمستندات لمدة:","o":["أربع سنوات تبدأ من آخر التواريخ المحددة في القانون","خمس سنوات تبدأ من تاريخ انتهاء السنة المالية","ثلاث سنوات تبدأ من تاريخ تقديم الإقرار","عشر سنوات تبدأ من تاريخ تنظيمها"],"a":0},{"q":"يشترط في السجلات والمستندات التي ينظمها المكلف أن تكون:","o":["معدة وفق معايير المحاسبة الدولية ومدققة ومصادق عليها من محاسب قانوني","مصادقاً عليها من المدير","مكتوبة باللغة العربية حصراً","مختومة من وزارة الصناعة والتجارة"],"a":0},{"q":"مكلف يمسك سجلاته باللغة الإنجليزية، فإن ذلك:","o":["جائز على أن يقدم ترجمة عربية لها إذا طلبت الدائرة ذلك","غير جائز في جميع الأحوال","جائز بموافقة الوزير المسبقة","جائز للشركات الأجنبية فقط"],"a":0},{"q":"إذا لم ينظم المكلف السجلات والمستندات وفق الأصول، فإن نسب القيم المضافة على المشتريات والمستوردات التي تحددها التعليمات التنفيذية تعتبر:","o":["قرينة قانونية","بينة قاطعة لا تقبل إثبات العكس","استرشادية غير ملزمة","غرامة إدارية"],"a":0}]},{"n":"39","chapter":"","notes":[],"source":"يجوز للمكلف استخدام أجهزة الحاسوب في تنظيم سجلاته ومستنداته وبياناته المالية وتعُتبر هذه السجلات والبيانات أصولية من الناحية المحاسبية إذا تم مراعاة ما يلي:\nأ- أن يحتفظ المكلف للمدة المقررة قانوناً بأصول المستندات والوثائق المعززة لها.\nب-أن يلتزم بأي شروط وإجراءات أخرى تحددها التعليمات التنفيذية لهذه الغاية.","title":"استخدام الحاسوب في تنظيم السجلات","memo":"⭐ يجوز للمكلف استخدام الحاسوب في تنظيم سجلاته ومستنداته وبياناته المالية وتعتبر أصولية محاسبياً\n⭐ شرطا ذلك: الاحتفاظ بأصول المستندات والوثائق المعززة للمدة المقررة قانوناً، والالتزام بشروط وإجراءات التعليمات التنفيذية","qs":[{"q":"تعتبر السجلات والبيانات المالية المنظمة بأجهزة الحاسوب أصولية من الناحية المحاسبية بشرط:","o":["أن يحتفظ المكلف للمدة المقررة قانوناً بأصول المستندات والوثائق المعززة لها","أن يصادق عليها محاسب قانوني مرخص سنوياً","أن يحصل المكلف على موافقة خطية مسبقة من الوزير","أن تودع نسخة إلكترونية منها لدى الدائرة كل ثلاثة أشهر"],"a":0},{"q":"الجهة التي تحدد الشروط والإجراءات الأخرى الواجب على المكلف الالتزام بها عند تنظيم سجلاته باستخدام الحاسوب هي:","o":["التعليمات التنفيذية","الأنظمة الصادرة عن مجلس الوزراء","قرار من هيئة الاعتراض","قرار من محكمة البداية الضريبية"],"a":0}]},{"n":"40","chapter":"","notes":[],"source":"يترتب على الشخص المرخص له بمزاولة مهنة محاسب قانوني في المملكة أن يقدم للدائرة بياناً بأسماء عملائه وعناوينهم خلال مدة لا تتجاوز نهاية الشهر الثالث من السنة اللاحقة للسنة المالية.","title":"بيان المحاسب القانوني بعملائه","memo":"⭐ على المحاسب القانوني المرخص تقديم بيان للدائرة بأسماء عملائه وعناوينهم\n⭐ المهلة: لا تتجاوز نهاية الشهر الثالث من السنة اللاحقة للسنة المالية","qs":[{"q":"يلتزم الشخص المرخص له بمزاولة مهنة محاسب قانوني بتقديم بيان بأسماء عملائه وعناوينهم للدائرة خلال مدة لا تتجاوز:","o":["نهاية الشهر الثالث من السنة اللاحقة للسنة المالية","نهاية الشهر الأول من السنة اللاحقة للسنة المالية","نهاية الشهر السادس من السنة اللاحقة للسنة المالية","ثلاثين يوماً من تاريخ التعاقد مع كل عميل"],"a":0},{"q":"يتضمن البيان الذي يقدمه المحاسب القانوني للدائرة وفق أحكام القانون:","o":["أسماء عملائه وعناوينهم","أسماء عملائه وأرقام مبيعاتهم السنوية","البيانات المالية المصادق عليها لعملائه","مقدار الضريبة المستحقة على كل عميل"],"a":0}]},{"n":"41","chapter":"","notes":[],"source":"أ- يقدم الإقرار الضريبي إلى الدائرة من قبل المسجل شخصياً أو من ينوب عنه أو بإحدى الوسائل التالية التي توافق الدائرة على اعتمادها وفق الشروط والإجراءات التي تحددها التعليمات التنفيذية:\n١- البريد المسجل.\n٢- البنوك.\n٣- أي شركة مرخصة للقيام بمهام مشغل البريد العام او مشغل البريد الخاص يعتمدها مجلس الوزراء بناء على تنسيب الوزير.\n٤- الوسائل الالكترونية.\nب-يعتبر تاريخ تقديم الإقرار الضريبي هو تاريخ تسلمه من قبل الدائرة أو تاريخ ختم البريد أو تاريخ وصل الإيداع لدى البنك أو الشركة المرخصة المعتمدة أيها أسبق، وفي حال إرساله الكترونيا تحُدد التعليمات التنفيذية التاريخ المعتمد لتقديمه.","title":"وسائل تقديم الإقرار الضريبي وتاريخه","memo":"⭐ يقدم الإقرار من المسجل شخصياً أو من ينوب عنه، أو بالبريد المسجل أو البنوك أو شركة بريد مرخصة يعتمدها مجلس الوزراء بتنسيب الوزير أو الوسائل الإلكترونية\n⭐ تاريخ التقديم: تاريخ تسلم الدائرة أو ختم البريد أو وصل الإيداع لدى البنك أو الشركة المعتمدة أيها أسبق\n⭐ الإرسال إلكترونياً: التعليمات التنفيذية تحدد التاريخ المعتمد","qs":[{"q":"الشركة المرخصة للقيام بمهام مشغل البريد التي يجوز تقديم الإقرار الضريبي بواسطتها يعتمدها:","o":["مجلس الوزراء بناء على تنسيب الوزير","الوزير بناء على تنسيب المدير","المدير بقرار منه","هيئة تنظيم قطاع الاتصالات"],"a":0},{"q":"أرسل مسجل إقراره بالبريد المسجل فختم البريد بتاريخ ١٠ ثم تسلمته الدائرة بتاريخ ١٤، يعتبر تاريخ تقديم الإقرار:","o":["تاريخ ختم البريد لأنه الأسبق","تاريخ تسلمه من الدائرة","التاريخ الذي يختاره المسجل","تاريخ قيد الإقرار في سجلات الدائرة بعد تدقيقه"],"a":0},{"q":"أي مما يلي ليس من الوسائل المنصوص عليها لتقديم الإقرار الضريبي:","o":["تسليمه لمحاسب قانوني ليودعه في المحكمة","البريد المسجل","البنوك","الوسائل الإلكترونية"],"a":0}]},{"n":"42","chapter":"","notes":[],"source":"للمسجل تعديل الإقرار الضريبي إذا تبين له وجود خطأ فيه وفي هذه الحالة يلُزم المسجل بدفع الضريبة وغرامة التأخير المستحقة نتيجة لذلك ولا يعتبر المسجل مرتكبا لمخالفة أو جرم ما لم تكن الدائرة قد سبقته الى اكتشاف هذا الخطأ أو ما لم يكن المدقق قد أصدر مذكرة تدقيق بشأن ذلك الاقرار.","title":"تعديل الإقرار الضريبي من المسجل","memo":"⭐ للمسجل تعديل إقراره إذا تبين له خطأ فيه، ويلتزم بدفع الضريبة وغرامة التأخير المستحقة\n⭐ لا يعتبر مرتكباً لمخالفة أو جرم ما لم تسبقه الدائرة لاكتشاف الخطأ أو يصدر المدقق مذكرة تدقيق بشأن الإقرار","qs":[{"q":"إذا عدّل المسجل إقراره الضريبي بعد اكتشافه خطأ فيه، فإنه يلزم بـ:","o":["دفع الضريبة وغرامة التأخير المستحقة نتيجة لذلك","دفع الضريبة فقط دون أي غرامة","دفع غرامة تعادل ضعف الضريبة","دفع الضريبة وتعويض مدني يعادل مثليها"],"a":0},{"q":"اكتشف مسجل خطأ في إقراره فعدّله قبل أن تكتشفه الدائرة وقبل صدور أي مذكرة تدقيق بشأنه، فإن المسجل:","o":["لا يعتبر مرتكباً لمخالفة أو جرم","يعتبر مرتكباً لجرم التهرب الضريبي","يعتبر مرتكباً لمخالفة تستوجب الغرامة","يحال إلى النيابة العامة الضريبية"],"a":0},{"q":"يعتبر المسجل الذي يعدّل إقراره الضريبي مرتكباً لمخالفة أو جرم في حالة:","o":["إذا كان المدقق قد أصدر مذكرة تدقيق بشأن ذلك الإقرار","إذا دفع الضريبة المستحقة نتيجة التعديل","إذا كان التعديل بزيادة الضريبة","إذا تم التعديل خلال السنة نفسها"],"a":0}]},{"n":"43","chapter":"","notes":[],"source":"أ- لا يجوز للمدقق تدقيق الإقرار الضريبي بعد مرور أربع سنوات على تاريخ تقديمه.\nب-يختار المدير الإقرارات الخاضعة للتدقيق وفق المعايير والأسس التي يراها مناسبة، فإذا ظهرت للمدقق نتيجة مراجعة الإقرار الضريبي أسبابا قد تستدعي عدم قبوله كليا أو جزئيا يصدر مذكرة تدقيق يدعو فيها المسجل لحضور جلسة لمناقشته على أن تتضمن:\n١- تاريخ المذكرة.\n٢- اسم المسجل ورقمه الضريبي.\n٣- الفترة أو الفترات الضريبية التي يشملها التدقيق.\n٤- مكان وتاريخ ووقت إجراء التدقيق.\n٥- اسم المدقق وتوقيعه.\nج- للمدقق إجراء التدقيق في مركز عمل المسجل أو أي مكان آخر يتعلق به.\nد- يجوز للمدقق بموافقة المدير الخطية إجراء التدقيق خارج أوقات العمل الرسمي.","title":"تدقيق الإقرار ومذكرة التدقيق","memo":"⭐ لا يجوز تدقيق الإقرار بعد مرور ٤ سنوات على تاريخ تقديمه\n⭐ المدير يختار الإقرارات الخاضعة للتدقيق؛ المدقق يصدر مذكرة تدقيق يدعو فيها المسجل لجلسة مناقشة\n⭐ التدقيق في مركز عمل المسجل أو أي مكان آخر يتعلق به؛ وخارج أوقات العمل الرسمي بموافقة المدير الخطية","qs":[{"q":"لا يجوز للمدقق تدقيق الإقرار الضريبي بعد مرور:","o":["أربع سنوات على تاريخ تقديمه","سنتين على تاريخ تقديمه","ثلاث سنوات على تاريخ تقديمه","ثماني سنوات على تاريخ تقديمه"],"a":0},{"q":"الجهة التي تختار الإقرارات الخاضعة للتدقيق هي:","o":["المدير","الوزير","هيئة الاعتراض","المدقق المختص"],"a":0},{"q":"يجوز للمدقق إجراء التدقيق خارج أوقات العمل الرسمي:","o":["بموافقة المدير الخطية","بموافقة المسجل الخطية","بقرار من محكمة البداية الضريبية","بموافقة الوزير"],"a":0},{"q":"جميع ما يلي من البيانات الواجب تضمينها في مذكرة التدقيق باستثناء:","o":["مقدار الضريبة المستحقة على المسجل","اسم المسجل ورقمه الضريبي","الفترة أو الفترات الضريبية التي يشملها التدقيق","اسم المدقق وتوقيعه"],"a":0}]},{"n":"44","chapter":"","notes":[],"source":"أ- يلتزم المدقق بإصدار قرار التدقيق خلال سنتين من تاريخ إصدار مذكرة التدقيق على أن يتضمن البيانات التالية:\n١- اسم المسجل ورقمه الضريبي.\n٢- الفترة أو الفترات الضريبية.\n٣- الأسس التي تم الاستناد إليها في التدقيق.\n٤- نتيجة التدقيق.\n٥- تحديد مقدار الضريبة وأي مبالغ أخرى مترتبة عليه وفق أحكام هذا القانون.\nب-إذا تضمن قرار التدقيق تعديلاً في الإقرار الضريبي فللمسجل بعد الاطلاع على مضمونه القيام بأي مما يلي:\n١- التوقيع بالموافقة على نتيجة القرار.\n٢- التوقيع بعدم الموافقة على نتيجة القرار ويعتبر امتناعه عن التوقيع أو تخلفه عن الحضور بمثابة عدم موافقة، ويكون القرار في هذه الحالة قابلا للاعتراض لدى هيئة الاعتراض.\nج- في جميع الأحوال يتم تبليغ المسجل إشعاراً خطياً بنتيجة قرار التدقيق.\nد- على الرغم من أي نص آخر لا يجوز للمدقق إصدار الإشعار الخطي بنتيجة قرار التدقيق بعد مرور أربع سنوات من تاريخ تقديم الإقرار الضريبي.","title":"قرار التدقيق والاعتراض عليه","memo":"⭐ يصدر قرار التدقيق خلال سنتين من تاريخ إصدار مذكرة التدقيق\n⭐ للمسجل التوقيع بالموافقة أو بعدم الموافقة؛ الامتناع عن التوقيع أو التخلف عن الحضور = عدم موافقة، والقرار قابل للاعتراض لدى هيئة الاعتراض\n⭐ لا يجوز إصدار الإشعار الخطي بنتيجة قرار التدقيق بعد ٤ سنوات من تاريخ تقديم الإقرار","qs":[{"q":"يلتزم المدقق بإصدار قرار التدقيق خلال:","o":["سنتين من تاريخ إصدار مذكرة التدقيق","سنة من تاريخ إصدار مذكرة التدقيق","أربع سنوات من تاريخ إصدار مذكرة التدقيق","تسعين يوماً من تاريخ إصدار مذكرة التدقيق"],"a":0},{"q":"تخلف المسجل عن الحضور للاطلاع على قرار التدقيق المتضمن تعديلاً لإقراره، فإن ذلك يعتبر:","o":["بمثابة عدم موافقة ويكون القرار قابلاً للاعتراض لدى هيئة الاعتراض","بمثابة موافقة ضمنية ويصبح القرار قطعياً","سبباً لإلغاء قرار التدقيق حكماً","سبباً لإصدار قرار تقدير أولي"],"a":0},{"q":"لا يجوز للمدقق إصدار الإشعار الخطي بنتيجة قرار التدقيق بعد مرور:","o":["أربع سنوات من تاريخ تقديم الإقرار الضريبي","سنتين من تاريخ تقديم الإقرار الضريبي","أربع سنوات من تاريخ إصدار مذكرة التدقيق","ثماني سنوات من تاريخ تقديم الإقرار الضريبي"],"a":0}]},{"n":"45","chapter":"","notes":[],"source":"أ- إذا تخلف المسجل عن تقديم الإقرار الضريبي خلال المدة المحددة في هذا القانون، تقوم الدائرة بإصدار قرار تقدير أوَلي تحدد فيه قيمة الضريبة المقدرة على المسجل عن الفترة أو الفترات الضريبية المعنية وأي غرامات ومبالغ أخرى متحققة عليه ويبلغ المسجل اشعاراَ خطياً بنتيجة ذلك القرار.\nب-تكون المبالغ المطالب بها بموجب الإشعار المنصوص عليه في الفقرة (أ) من هذه المادة واجبة التحصيل بعد مرور ثلاثين يوما من تاريخ تبليغه للمسجل ويعتبر أي مبلغ محصل منها دفعة على حساب الضريبة النهائية المستحقة عليه ولا يعتبر هذا القرار نهائياً لغايات الاعتراض أو الطعن القضائي.\nج- يعتبر قرار التقدير الأوَلي ملغى حكماً إذا قدمَ المسجل الإقرار الضريبي عن الفترة أو الفترات الضريبية المعنية ودفع الضريبة وأي غرامات أو مبالغ أخرى مترتبة عليه بموجب ذلك الإقرار على أن يتم ذلك قبل صدور قرار التقدير الإداري وفق أحكام المادة (٤٦) من هذا القانون.\nد- لغايات هذه المادة يصدر المدير تعليمات لتحديد أسس وإجراءات التقدير الأوَلي.","title":"قرار التقدير الأولي","memo":"⭐ عند التخلف عن تقديم الإقرار تصدر الدائرة قرار تقدير أولي وتبلغ المسجل إشعاراً خطياً\n⭐ المبالغ واجبة التحصيل بعد ٣٠ يوماً من التبليغ، وتعتبر دفعة على حساب الضريبة النهائية، والقرار ليس نهائياً لغايات الاعتراض أو الطعن\n⭐ يلغى حكماً إذا قدم المسجل الإقرار ودفع الضريبة والغرامات قبل صدور قرار التقدير الإداري\n⭐ المدير يصدر تعليمات أسس وإجراءات التقدير الأولي","qs":[{"q":"تكون المبالغ المطالب بها بموجب إشعار قرار التقدير الأولي واجبة التحصيل بعد مرور:","o":["ثلاثين يوماً من تاريخ تبليغه للمسجل","عشرة أيام من تاريخ تبليغه للمسجل","ستين يوماً من تاريخ تبليغه للمسجل","تسعين يوماً من تاريخ تبليغه للمسجل"],"a":0},{"q":"أي مما يلي صحيح بشأن قرار التقدير الأولي:","o":["لا يعتبر نهائياً لغايات الاعتراض أو الطعن القضائي","يقبل الاعتراض لدى هيئة الاعتراض خلال ثلاثين يوماً","يقبل الطعن مباشرة لدى محكمة البداية الضريبية","يصبح قطعياً بمرور ثلاثين يوماً على تبليغه"],"a":0},{"q":"صدر بحق مسجل قرار تقدير أولي، ثم قدّم الإقرار الضريبي عن الفترة المعنية ودفع الضريبة والغرامات المترتبة قبل صدور قرار التقدير الإداري، فإن قرار التقدير الأولي:","o":["يعتبر ملغى حكماً","يبقى نافذاً ويعتبر المبلغ المدفوع دفعة على الحساب","يتحول إلى قرار تقدير إداري","يحال إلى هيئة الاعتراض للبت فيه"],"a":0},{"q":"الجهة التي تصدر التعليمات لتحديد أسس وإجراءات التقدير الأولي هي:","o":["المدير","مجلس الوزراء","الوزير","هيئة الاعتراض"],"a":0}]},{"n":"46","chapter":"","notes":[],"source":"أ- إذا لم يقدم المسجل اقراراً ضريبياً بعد مرور ثلاثين يوما من تاريخ تبلغه الإشعار الخطي بنتيجة قرار التقدير الأولي فيجوز للمدقق إصدار قرار تقدير إداري بالاستعانة بأي من مصادر المعلومات التي تحددها التعليمات التنفيذية.\nب-يتم تبليغ المسجل اشعاراً خطياً بنتيجة قرار التقدير الإداري ويكون هذا القرار قابلاً للاعتراض لدى هيئة الاعتراض.\nج- يعتبر قرار التقدير الأولي ملغى حكماً بصدور قرار التقدير الإداري.","title":"قرار التقدير الإداري لعدم تقديم الإقرار","memo":"⭐ إذا لم يقدم المسجل الإقرار بعد ٣٠ يوماً من تبلغه إشعار التقدير الأولي يجوز للمدقق إصدار قرار تقدير إداري\n⭐ قرار التقدير الإداري قابل للاعتراض لدى هيئة الاعتراض\n⭐ يعتبر قرار التقدير الأولي ملغى حكماً بصدور قرار التقدير الإداري","qs":[{"q":"يجوز للمدقق إصدار قرار تقدير إداري إذا لم يقدم المسجل إقراره الضريبي بعد مرور:","o":["ثلاثين يوماً من تاريخ تبلغه الإشعار الخطي بنتيجة قرار التقدير الأولي","عشرة أيام من تاريخ تبلغه الإشعار الخطي بنتيجة قرار التقدير الأولي","ستين يوماً من انتهاء الفترة الضريبية","تسعين يوماً من تاريخ تبلغه الإشعار الخطي بنتيجة قرار التقدير الأولي"],"a":0},{"q":"يكون قرار التقدير الإداري الصادر بحق المسجل لعدم تقديمه الإقرار قابلاً للاعتراض لدى:","o":["هيئة الاعتراض","محكمة الاستئناف الضريبية","الوزير","محكمة التمييز"],"a":0},{"q":"أثر صدور قرار التقدير الإداري على قرار التقدير الأولي:","o":["يعتبر قرار التقدير الأولي ملغى حكماً","يبقى قرار التقدير الأولي نافذاً إلى جانبه","يصبح قرار التقدير الأولي قطعياً","يحال قرار التقدير الأولي إلى المحكمة"],"a":0}]},{"n":"47","chapter":"","notes":[],"source":"أ- إذا تبين للدائرة بأن شخصاً يقوم ببيع سلع أو خدمات خاضعة للضريبة ولم يقم بالتسجيل وفق أحكام هذا القانون وأن القيمة المقدرة لمبيعاته قد تتجاوز حد التسجيل فيجوز للمدقق إصدار قرار تقدير إداري يحدد فيه قيمة الضريبة المقدرة عليه عن الفترة أو الفترات الضريبية المعنية وأي غرامات أو مبالغ أخرى متحققة عليه ويبلغ المكلف اشعاراً خطياً بنتيجة ذلك القرار ويكون هذا القرار قابلاً للاعتراض لدى هيئة الاعتراض.\nب-لغايات هذه المادة تصدر التعليمات التنفيذية لتحديد أسس وإجراءات التقدير الإداري.","title":"التقدير الإداري لغير المسجل","memo":"⭐ إذا باع شخص سلعاً أو خدمات خاضعة ولم يسجل وقد تتجاوز مبيعاته المقدرة حد التسجيل يجوز للمدقق إصدار قرار تقدير إداري\n⭐ القرار يبلغ إشعاراً خطياً ويقبل الاعتراض لدى هيئة الاعتراض\n⭐ التعليمات التنفيذية تحدد أسس وإجراءات هذا التقدير","qs":[{"q":"تبين للدائرة أن شخصاً غير مسجل يبيع سلعاً خاضعة للضريبة وأن القيمة المقدرة لمبيعاته قد تتجاوز حد التسجيل، فيجوز للمدقق:","o":["إصدار قرار تقدير إداري بالضريبة المقدرة عليه وأي غرامات","إصدار قرار تقدير أولي غير قابل للاعتراض","إحالته مباشرة إلى محكمة التمييز","إلغاء نشاطه التجاري بقرار منه"],"a":0},{"q":"يكون قرار التقدير الإداري الصادر بحق الشخص غير المسجل:","o":["قابلاً للاعتراض لدى هيئة الاعتراض","قطعياً لا يقبل أي طعن","قابلاً للطعن لدى محكمة التمييز مباشرة","خاضعاً لمصادقة مجلس الوزراء"],"a":0}]},{"n":"48","chapter":"","notes":[],"source":"أ- تشكل بقرار من المدير هيئة إدارية واحدة أو أكثر تسمى (هيئة الاعتراض) للبت في الاعتراضات المقدمة وفق أحكام هذا القانون تتألف كل منها من مدقق أو أكثر من ذوي الخبرة والاختصاص وتحدد التعليمات إجراءات عمل هذه الهيئة وكيفية اتخاذ قراراتها.\nب- يجوز للمكلف الاعتراض لدى هيئة الاعتراض على قرار التدقيق أو قرار التقدير الإداري بمقتضى البند (٢) من الفقرة (ب) من المادة (٤٤) والمادتين (٤٦) و(٤٧) من هذا القانون خلال مدة لا تزيد على ثلاثين يوماً من تاريخ تبليغه القرار.\nج- يعتبر قرار التدقيق أو قرار التقدير الإداري قطعياً ونهائياً إذا لم يقدم الاعتراض إلى هيئة الاعتراض خلال المدة المحددة في الفقرة (ب) من هذه المادة ما لم تقتنع هيئة الاعتراض بأن الشخص المعترض لم يتمكن من تقديم اعتراضه خلال المدة المذكورة من جراء غيابه خارج المملكة أو مرضه او لأي سبب معقول آخر وفي هذه الحالة يجوز لها أن تمدد تلك المدة إلى الأجل الذي تراه مناسبا.\nد- يلتزم المكلف بدفع الضريبة والغرامات والمبالغ الأخرى المسلم بها تحت طائلة رد الاعتراض شكلاً.\nه- تدعو هيئة الاعتراض المعترض إلى جلسة للنظر في اعتراضه وللمعترض حق تقديم البينة على أسباب اعتراضه، ولهيئة الاعتراض حق طلب المعلومات والتفاصيل الضرورية وطلب إبراز السجلات والمستندات المتعلقة بمبيعات المعترض كما لها استجواب أي شخص يعتقد أن لديه معلومات تتعلق بالقرار المعترض عليه.\nو- تصدر هيئة الاعتراض قرارا معللا بشأن الاعتراض خلال (٩٠) يوما من تاريخ تقديمه ولها تأييد القرار المعترض عليه أو تعديله سواء بزيادة الضريبة أو تخفيضها أو الغاءها.\nز- للمكلف بعد الاطلاع على مضمون القرار الصادر بمقتضى الفقرة (و) من هذه المادة القيام بأي مما يلي:\n١- التوقيع بالموافقة على نتيجة القرار.\n٢- التوقيع بعدم الموافقة على نتيجة القرار ويعتبر امتناعه عن التوقيع أو تخلفه عن الحضور بمثابة عدم موافقة.\nح- تقوم الدائرة بتبليغ المكلف إشعارا خطيا بنتيجة القرار الصادر بشأن الاعتراض وللمكلف في حال عدم الموافقة عليه الطعن به لدى المحكمة خلال ثلاثين يوما من تاريخ تبليغه الإشعار.\nط- إذا لم تصدر هيئة الاعتراض قرارا بشأن الاعتراض خلال المدة المحددة في الفقرة (و) من هذه المادة فلا تحسب أي غرامة تأخير عن الفترة من تاريخ انقضاء المدة المذكورة ولحين صدور الإشعار المتضمن نتيجة القرار.","title":"هيئة الاعتراض وإجراءات الاعتراض","memo":"⭐ تشكل هيئة الاعتراض بقرار من المدير من مدقق أو أكثر من ذوي الخبرة\n⭐ مدة الاعتراض: لا تزيد على ٣٠ يوماً من التبليغ؛ وإلا أصبح القرار قطعياً ما لم تقتنع الهيئة بعذر (غياب خارج المملكة، مرض، سبب معقول) فتمدد\n⭐ يدفع المكلف المبالغ المسلم بها تحت طائلة رد الاعتراض شكلاً؛ الهيئة تصدر قراراً معللاً خلال (٩٠) يوماً\n⭐ الطعن لدى المحكمة خلال ٣٠ يوماً من تبليغ الإشعار؛ تأخر الهيئة عن ٩٠ يوماً = لا تحسب غرامة تأخير بعد انقضائها","qs":[{"q":"تشكل هيئة الاعتراض بقرار من:","o":["المدير","الوزير","مجلس الوزراء","رئيس النيابة العامة الضريبية"],"a":0},{"q":"تصدر هيئة الاعتراض قرارها المعلل بشأن الاعتراض خلال:","o":["(٩٠) يوماً من تاريخ تقديمه","(٣٠) يوماً من تاريخ تقديمه","(٦٠) يوماً من تاريخ تقديمه","سنتين من تاريخ تقديمه"],"a":0},{"q":"لم يدفع المكلف الضريبة والغرامات والمبالغ المسلم بها عند تقديم اعتراضه، فإن النتيجة هي:","o":["رد الاعتراض شكلاً","رد الاعتراض موضوعاً","تمديد مدة النظر في الاعتراض","إحالة الاعتراض إلى المحكمة"],"a":0},{"q":"تأخرت هيئة الاعتراض في إصدار قرارها عن المدة المحددة قانوناً، فإن الأثر المترتب على ذلك:","o":["لا تحسب أي غرامة تأخير عن الفترة من تاريخ انقضاء المدة ولحين صدور الإشعار بنتيجة القرار","يعتبر الاعتراض مقبولاً حكماً","يعتبر القرار المعترض عليه ملغى","تخفض الضريبة بنسبة غرامة التأخير"],"a":0}]},{"n":"49","chapter":"","notes":[],"source":"أ- مع مراعاة أحكام الفقرة (ب) من هذه المادة يجوز للمدير أو من يفوضه خلال مدة لا تزيد على أربع سنوات من تاريخ تقديم الإقرار الضريبي أو تاريخ إصدار قرار التقدير الاداري وفق أحكام المادة (٤٦) من هذا القانون أو خلال مدة لا تزيد على ثماني سنوات من تاريخ إصدار قرار التقدير الإداري وفق أحكام المادة (٤٧) من هذا القانون أن يقرر إعادة النظر في قرار التدقيق أو قرار التقدير الإداري أو القرار الصادر عن هيئة الاعتراض بشأن أي منها وبعد أن يتُيح المدير أو من يفوضه للمكلف فرصة معقولة لسماع أقواله وبسط قضيته فله إصدار قرار معدل لأي من هذه القرارات لزيادة الضريبة إذا ثبت:\n١- وجود خطأ في تطبيق القانون، أو\n٢- إغفال القرار السابق لحقيقة أو واقعة او لوجود مبيعات لم تعالج في حينه.\nب-لا يجوز أن يتضمن القرار المعدل لقرار التدقيق أو قرار التقدير الإداري والقرار الصادر عن هيئة الاعتراض أي من الوقائع التي فصلت فيها المحكمة عندما نظرت في الطعن المقدم بشأن ذلك القرار.\nج- تقوم الدائرة بتبليغ المكلف إشعاراً خطياً بنتيجة القرار المعدل الصادر بمقتضى أحكام هذه المادة ويكون هذا القرار قابلاً للطعن أمام المحكمة خلال ثلاثين يوماً من تاريخ تبليغ الاشعار للمكلف.","title":"إعادة النظر وإصدار القرار المعدل","memo":"⭐ للمدير أو من يفوضه إعادة النظر خلال ٤ سنوات من تقديم الإقرار أو قرار التقدير الإداري (م٤٦)، أو خلال ٨ سنوات من قرار التقدير الإداري (م٤٧)\n⭐ يصدر قرار معدل لزيادة الضريبة إذا ثبت خطأ في تطبيق القانون أو إغفال حقيقة أو واقعة أو مبيعات لم تعالج\n⭐ لا يتضمن القرار المعدل وقائع فصلت فيها المحكمة؛ ويطعن فيه أمام المحكمة خلال ٣٠ يوماً من التبليغ","qs":[{"q":"المدة التي يجوز خلالها للمدير إعادة النظر في قرار التقدير الإداري الصادر بحق شخص غير مسجل وفق المادة (٤٧) هي:","o":["مدة لا تزيد على ثماني سنوات من تاريخ إصدار القرار","مدة لا تزيد على أربع سنوات من تاريخ إصدار القرار","مدة لا تزيد على سنتين من تاريخ إصدار القرار","مدة لا تزيد على ثلاث سنوات من تاريخ إصدار القرار"],"a":0},{"q":"يجوز للمدير إصدار قرار معدل لزيادة الضريبة إذا ثبت:","o":["إغفال القرار السابق لوجود مبيعات لم تعالج في حينه","تأخر المكلف في دفع الضريبة","اعتراض المكلف على القرار لدى الهيئة","عدم توقيع المكلف على القرار"],"a":0},{"q":"يكون القرار المعدل الصادر وفق أحكام إعادة النظر قابلاً للطعن:","o":["أمام المحكمة خلال ثلاثين يوماً من تاريخ تبليغ الإشعار","لدى هيئة الاعتراض خلال ثلاثين يوماً","أمام المحكمة خلال تسعين يوماً من تاريخ تبليغ الإشعار","لدى الوزير خلال عشرة أيام"],"a":0},{"q":"لا يجوز أن يتضمن القرار المعدل:","o":["أياً من الوقائع التي فصلت فيها المحكمة عند نظرها الطعن في ذلك القرار","زيادة في الضريبة المستحقة","تصحيحاً لخطأ في تطبيق القانون","مبيعات لم تعالج في حينه"],"a":0}]},{"n":"50","chapter":"","notes":[],"source":"للمدير بتعليمات خاصة يصدرها لهذه الغاية إخضاع قرارات التدقيق وقرارات التقدير الإداري والقرارات الصادرة عن هيئة الاعتراض بشأن أي منها والقرارات المعدلة لها وأي قرارات أخرى صادرة وفق أحكام هذا القانون للتدقيق من قبله مباشرة أو من قبل من يفوضه المدير لهذه الغاية من موظفي الدائرة ولا يكون أي من هذه القرارات الخاضعة للتدقيق بمقتضى أحكام هذه المادة نهائياً وملزماً ولا ينتج أي اثر قبل المصادقة عليه من المدير أو من يفوضه لهذه الغاية ويعتبر أي تبليغ له قبل المصادقة عليه باطلاً ويفصل المدير في أي مسألة او خلاف ينشأ عن هذا التدقيق.","title":"تدقيق المدير للقرارات ومصادقتها","memo":"⭐ للمدير بتعليمات خاصة إخضاع القرارات للتدقيق من قبله مباشرة أو ممن يفوضه من موظفي الدائرة\n⭐ القرار الخاضع لهذا التدقيق لا يكون نهائياً ولا ملزماً ولا ينتج أثراً قبل مصادقة المدير أو من يفوضه\n⭐ أي تبليغ للقرار قبل المصادقة باطل؛ والمدير يفصل في أي خلاف ينشأ عن هذا التدقيق","qs":[{"q":"تبليغ المكلف بقرار تدقيق خاضع لتدقيق المدير قبل المصادقة عليه يعتبر:","o":["باطلاً","صحيحاً منتجاً لآثاره","قابلاً للإبطال بقرار من المحكمة","صحيحاً بشرط موافقة المكلف"],"a":0},{"q":"الجهة التي تفصل في أي مسألة أو خلاف ينشأ عن تدقيق المدير للقرارات هي:","o":["المدير","هيئة الاعتراض","محكمة البداية الضريبية","الوزير"],"a":0}]},{"n":"51","chapter":"","notes":[],"source":"أ- في حال عدم دفع الضريبة أو توريدها في المواعيد المحددة بموجب أحكام هذا القانون تستوفي الدائرة غرامة تأخير بنسبة أربعة بالألف من قيمة الضريبة المستحقة وذلك عن كل أسبوع تأخير أو أي جزء منه.\nب-تحدد التعليمات التنفيذية طرق دفع الضريبة وتوريدها وأي إجراءات أخرى لازمة لذلك.","title":"غرامة التأخير","memo":"⭐ غرامة تأخير بنسبة ٤ بالألف من قيمة الضريبة المستحقة عن كل أسبوع تأخير أو جزء منه\n⭐ التعليمات التنفيذية تحدد طرق دفع الضريبة وتوريدها","qs":[{"q":"تستوفي الدائرة غرامة تأخير عند عدم دفع الضريبة في موعدها بنسبة:","o":["أربعة بالألف من قيمة الضريبة المستحقة عن كل أسبوع تأخير أو أي جزء منه","أربعة بالمائة من قيمة الضريبة المستحقة عن كل شهر تأخير","(٩%) سنوياً من قيمة الضريبة المستحقة","واحد بالألف من قيمة الضريبة المستحقة عن كل يوم تأخير"],"a":0},{"q":"تأخر مكلف عن توريد ضريبة مستحقة قيمتها (١٠٠٠٠) دينار مدة أسبوعين وثلاثة أيام، فإن غرامة التأخير المستحقة عليه:","o":["(١٢٠) ديناراً","(٨٠) ديناراً","(٤٠) ديناراً","(٤٠٠) دينار"],"a":0}]},{"n":"52","chapter":"","notes":[],"source":"أ- للمدير ولأسباب مبررة تقسيط المبلغ المستحق على المكلف وفق الشروط والإجراءات التي تحددها التعليمات التنفيذية.\nب-يلزم المكلف بدفع مبلغ اضافي على المبلغ المقسط بنسبة (%٩) سنويا.","title":"تقسيط المبالغ المستحقة","memo":"⭐ للمدير لأسباب مبررة تقسيط المبلغ المستحق وفق التعليمات التنفيذية\n⭐ يدفع المكلف مبلغاً إضافياً على المبلغ المقسط بنسبة (٩%) سنوياً","qs":[{"q":"الجهة المختصة بتقسيط المبلغ المستحق على المكلف لأسباب مبررة هي:","o":["المدير","الوزير","مجلس الوزراء","محكمة البداية الضريبية"],"a":0},{"q":"يلزم المكلف عند تقسيط المبلغ المستحق عليه بدفع مبلغ إضافي على المبلغ المقسط بنسبة:","o":["(٩%) سنوياً","أربعة بالألف أسبوعياً","(٥%) سنوياً","(١٢%) سنوياً"],"a":0}]},{"n":"53","chapter":"","notes":[],"source":"أ-\n١- إذا دفع المكلف مبلغاً يزيد على المبالغ المستحقة عليه فعلى الدائرة تحويل الرصيد الزائد لتسديد أي مبالغ أخرى مستحقة عليه للدائرة بمقتضى أحكام التشريعات النافذة، وإذا تبقى أي مبلغ من هذا الرصيد تلزم الدائرة برده إلى المكلف خلال مدة لا تزيد على ثلاثة أشهر من تاريخ تسلمها طلبا خطيا بذلك.\n٢- إذا لم ترد الدائرة الرصيد الزائد في الموعد المحدد في الفقرة (أ) من هذه المادة فتلُزم بدفع فائدة بنسبة (%٩) سنوياً.\nب-لا ينظر في أي مطالبة أو دعوى باسترداد الضريبة أو الغرامات التي مضى على تأديتها أكثر من ثلاث سنوات.\nج- لا تسقط حقوق الدائرة المالية الثابتة بحكم قضائي أو بإقرار من المكلف بمرور الزمن.","title":"رد الرصيد الزائد والتقادم","memo":"⭐ الرصيد الزائد يحول أولاً لتسديد مبالغ أخرى مستحقة للدائرة، والباقي يرد خلال مدة لا تزيد على ٣ أشهر من تسلم طلب خطي\n⭐ إذا لم ترده في الموعد تلزم الدائرة بفائدة (٩%) سنوياً\n⭐ لا ينظر في مطالبة باسترداد ضريبة أو غرامات مضى على تأديتها أكثر من ٣ سنوات\n⭐ حقوق الدائرة الثابتة بحكم قضائي أو بإقرار المكلف لا تسقط بمرور الزمن","qs":[{"q":"تلتزم الدائرة برد الرصيد الزائد المتبقي للمكلف خلال مدة لا تزيد على:","o":["ثلاثة أشهر من تاريخ تسلمها طلباً خطياً بذلك","ثلاثين يوماً من تاريخ تسلمها طلباً خطياً بذلك","ستة أشهر من تاريخ تسلمها طلباً خطياً بذلك","سنة من تاريخ دفع المبلغ الزائد"],"a":0},{"q":"إذا لم ترد الدائرة الرصيد الزائد في الموعد المحدد فإنها تلزم بدفع فائدة بنسبة:","o":["(٩%) سنوياً","أربعة بالألف أسبوعياً","(٤%) سنوياً","(٦%) سنوياً"],"a":0},{"q":"لا ينظر في أي مطالبة أو دعوى باسترداد الضريبة أو الغرامات التي مضى على تأديتها أكثر من:","o":["ثلاث سنوات","أربع سنوات","خمس سنوات","سنتين"],"a":0},{"q":"حقوق الدائرة المالية الثابتة بحكم قضائي أو بإقرار من المكلف:","o":["لا تسقط بمرور الزمن","تسقط بمرور ثلاث سنوات","تسقط بمرور أربع سنوات","تسقط بمرور ثماني سنوات"],"a":0}]},{"n":"54","chapter":"","notes":[],"source":"أ- إذا لم يتم دفع الضريبة أو المبالغ المستحقة للدائرة خلال المدد المنصوص عليها في هذا القانون، فعلى الدائرة مطالبة المكلف بدفعها خلال ثلاثين يوما من تاريخ التبليغ وإذا تخلف المكلف عن ذلك يتم تحصيلها وفق أحكام قانون تحصيل الأموال الأميرية النافذ، ويمارس المدير أو من يفوضه جميع الصلاحيات المخولة للحاكم الإداري وللجنة تحصيل الأموال الأميرية المنصوص عليها في ذلك القانون.\nب-يعتبر تبليغ المكلف بوجوب دفع الضريبة والمبالغ المستحقة عليه وفق أحكام الفقرة (أ) من هذه المادة كافيا لغايات مباشرة المدير أو من يفوضه إجراءات الحجز والتنفيذ وفق أحكام قانون تحصيل الأموال الأميرية النافذ وذلك دون حاجة لاتخاذ أي من إجراءات التبليغ أو النشر المنصوص عليها في المادتين (٦) و(٧) من القانون المذكور.","title":"تحصيل الضريبة وفق قانون تحصيل الأموال الأميرية","memo":"⭐ تطالب الدائرة المكلف بالدفع خلال ٣٠ يوماً من التبليغ، وإلا تحصل وفق قانون تحصيل الأموال الأميرية\n⭐ يمارس المدير أو من يفوضه صلاحيات الحاكم الإداري ولجنة تحصيل الأموال الأميرية\n⭐ التبليغ كافٍ لمباشرة الحجز والتنفيذ دون إجراءات التبليغ أو النشر في المادتين (٦) و(٧) من قانون التحصيل","qs":[{"q":"إذا لم يدفع المكلف المبالغ المستحقة خلال المدد القانونية، تطالبه الدائرة بدفعها خلال:","o":["ثلاثين يوماً من تاريخ التبليغ","عشرة أيام من تاريخ التبليغ","ستين يوماً من تاريخ التبليغ","تسعين يوماً من تاريخ التبليغ"],"a":0},{"q":"يمارس المدير أو من يفوضه عند تحصيل المبالغ المستحقة وفق قانون تحصيل الأموال الأميرية صلاحيات:","o":["الحاكم الإداري ولجنة تحصيل الأموال الأميرية","المحكمة الإدارية","النائب العام","وزير المالية"],"a":0},{"q":"يعتبر تبليغ المكلف بوجوب دفع الضريبة والمبالغ المستحقة كافياً لمباشرة إجراءات الحجز والتنفيذ:","o":["دون حاجة لإجراءات التبليغ أو النشر المنصوص عليها في المادتين (٦) و(٧) من قانون تحصيل الأموال الأميرية","بعد نشره مرتين في صحيفتين يوميتين","بعد مصادقة الوزير على التبليغ","بعد صدور حكم قطعي من المحكمة"],"a":0}]},{"n":"55","chapter":"","notes":[],"source":"أ- على الرغم مما ورد في أي تشريع آخر للمدير إصدار قرار بإلقاء الحجز التحفظي على الأموال المنقولة وغير المنقولة العائدة لأي مكلف أو منعه من السفر إذا كانت الدائرة تطالبه بدفع الضريبة أو أي مبالغ أخرى تزيد على ألفي دينار ترتبت بموجب أحكام هذا القانون ووجدت دلائل كافية لدى الدائرة بان هذا المكلف قد يقوم بتهريب أمواله أو التصرف بها بقصد منع التنفيذ عليها بأي شكل من الأشكال.\nب-يخضع قرار منع السفر الصادر بمقتضى احكام الفقرة (أ) من هذه المادة لمصادقة الوزير.\nج- يكون قرار إلقاء الحجز التحفظي وقرار منع السفر الصادر بمقتضى احكام الفقرة (أ) من هذه المادة قابلاً للطعن لدى المحكمة.","title":"الحجز التحفظي ومنع السفر","memo":"⭐ للمدير إلقاء الحجز التحفظي على أموال المكلف المنقولة وغير المنقولة أو منعه من السفر إذا كانت المطالبة تزيد على ألفي دينار ووجدت دلائل كافية على تهريب الأموال\n⭐ قرار منع السفر يخضع لمصادقة الوزير\n⭐ قرارا الحجز التحفظي ومنع السفر قابلان للطعن لدى المحكمة","qs":[{"q":"يشترط لإصدار المدير قراراً بالحجز التحفظي على أموال المكلف أن تكون المبالغ المطالب بها تزيد على:","o":["ألفي دينار","ألف دينار","خمسة آلاف دينار","خمسمائة دينار"],"a":0},{"q":"يخضع قرار منع السفر الصادر عن المدير بحق المكلف لمصادقة:","o":["الوزير","مجلس الوزراء","محكمة البداية الضريبية","رئيس النيابة العامة الضريبية"],"a":0},{"q":"قرار إلقاء الحجز التحفظي وقرار منع السفر الصادران عن المدير:","o":["قابلان للطعن لدى المحكمة","قابلان للاعتراض لدى هيئة الاعتراض فقط","قطعيان لا يقبلان الطعن","قابلان للتظلم لدى رئيس الوزراء"],"a":0}]},{"n":"56","chapter":"","notes":[],"source":"على المدير اتخاذ ما يلزم لمراعاة ما يلي:\nأ- إذا كان المبلغ المحجوز نقدا فلا يجوز أن يتجاوز هذا المبلغ مقدار الضريبة والغرامات والمبالغ الأخرى المستحقة.\nب-إذا كان المبلغ المحجوز من غير النقود فيقوم المدير وبناء على طلب المكلف باتخاذ ما يلزم من إجراءات لتقدير قيمة المال المحجوز واقتصار الحجز على ما يعادل ضعف قيمة الضريبة والغرامات والمبالغ الأخرى المترتبة بمقتضى أحكام هذا القانون، وتكون مصاريف التقدير على نفقة المكلف.","title":"حدود المال المحجوز","memo":"⭐ الحجز النقدي: لا يتجاوز مقدار الضريبة والغرامات والمبالغ المستحقة\n⭐ الحجز على غير النقود: بطلب المكلف يقدر المال ويقتصر الحجز على ما يعادل ضعف المبالغ المترتبة، ومصاريف التقدير على نفقة المكلف","qs":[{"q":"إذا كان المال المحجوز من غير النقود فيقتصر الحجز بناءً على طلب المكلف على ما يعادل:","o":["ضعف قيمة الضريبة والغرامات والمبالغ الأخرى المترتبة","قيمة الضريبة والغرامات فقط","ثلاثة أضعاف قيمة الضريبة المترتبة","نصف قيمة الضريبة والغرامات"],"a":0},{"q":"تكون مصاريف تقدير قيمة المال المحجوز من غير النقود على نفقة:","o":["المكلف","الدائرة","الخزينة العامة مناصفة مع المكلف","المحكمة المختصة"],"a":0}]},{"n":"57","chapter":"","notes":[],"source":"أ- تختص محكمة البداية الضريبية بالنظر في جميع الدعاوى والخلافات الناشئة عن تطبيق أحكام هذا القانون والأنظمة والتعليمات الصادرة بمقتضاه مهما كانت قيمتها وبغض النظر عن طبيعتها جزائية أو حقوقية أو إدارية، وسواء كانت المطالبة موضوع الدعوى متعلقة بالضريبة أو الغرامات بما في ذلك أي غرامات بمثابة تعويض مدني وغرامة التأخير أو أي مبالغ اخرى يتعين دفعها أو توريدها أو ردها بمقتضى أحكام هذا القانون بما في ذلك ما يلي:\n١- الدعاوى المقامة للطعن في القرارات الصادرة عن هيئة الاعتراض وفق أحكام البند (٢) من الفقرة (ز) من المادة (٤٨) من هذا القانون.\n٢- القرارات المعدلة لقرارات التدقيق أو لقرارات التقدير الإداري أو للقرارات الصادرة عن هيئة الاعتراض القابلة للطعن وفق أحكام هذا القانون.\n٣- الجرائم التي ترتكب خلافاً لأحكام هذا القانون.\n٤- الطلبات المقدمة للطعن في قرارات إلقاء الحجز التحفظي أو المنع من السفر.\nب-\n١- تكون جميع الأحكام الصادرة عن محكمة البداية الضريبية قابلة للطعن لدى محكمة الاستئناف الضريبية ويتم النظر فيها مرافعة.\n٢- تكون الأحكام الصادرة عن محكمة الاستئناف الضريبية قابلة للطعن لدى محكمة التمييز وفق أحكام التشريعات النافذة.\n٣- تجري المحاكمة لدى المحكمة بصورة علنية إلا إذا أمرت المحكمة خلاف ذلك وتعطى الدعاوى والطلبات المنظورة أمامها صفة الاستعجال.\nج- يستوفى الرسم المقرر للدعوى عن كل فترة ضريبية بصورة مستقلة.\nد- على المكلف أن يبين في لائحة دعواه المبلغ الذي يسلم به وأن يقدم للمحكمة مع لائحة دعواه إيصالاً بدفعه وترد الدعوى إذا لم يدفع المبلغ المحدد في هذه الفقرة على ذلك الوجه.\nه- يقع على المكلف إقامة الدليل على أن المبالغ التي حددها القرار المطعون فيه باهظةً ولا يجوز إثبات أي وقائع لم يدع بها لدى الجهة التي اصدرت ذلك القرار.\nو- للمحكمة أن تؤيد ما ورد في القرار المطعون فيه أو أن تخفض أو تزيد أو تلغي الضريبة والمبالغ الأخرى المقررة بموجبه، كما لها أن تعيد القضية إلى مصدر القرار المطعون فيه لإعادة النظر فيه.\nز- إذا صدر قرار معدل عن المدير أو من يفوضه وفق أحكام المادة (٤٩) من هذا القانون وأقام المكلف دعوى لدى المحكمة للطعن في هذا القرار يترتب على المحكمة إسقاط أي دعوى أقامها المكلف للطعن في قرار هيئة الاعتراض المتعلق بالفترة الضريبية ذاتها وتقوم محكمة البداية الضريبية بالنظر في الدعوى المقامة للطعن في القرار المعدل بعد أن يقوم المكلف بدفع الفرق بين الرسم المترتب على الدعوى ضد قرار هيئة الاعتراض والرسم المترتب على الدعوى ضد القرار المعدل.\nح- تتولى الدائرة تبليغ المكلف خطياً بمقدار الضريبة والمبالغ الأخرى المستحقة عليه وفق قرار المحكمة.\nط-\n١- إذا تم إسقاط الدعوى بسبب الغياب أو لأي سبب آخر، ولم يتم تجديدها يعتبر القرار المطعون فيه قطعياً بعد مرور مدة ثلاثين يوما من تاريخ تبليغ الدائرة للمكلف وفق أحكام هذا القانون إشعارا خطيا بصدور قرار عن المحكمة بإسقاط الدعوى.\n٢- في كل الاحوال لا يجوز تجديد الدعوى وفق أحكام البند (١) من هذه الفقرة للسبب نفسه لأكثر من مرتين.\nي- إذا أوقفت الدعوى بحكم القانون لوفاة المكلف أو إفلاسه أو تصفيته أثناء النظر فيها من قبل محكمة البداية الضريبية أو محكمة الاستئناف الضريبية، فيجب متابعة السير في الدعوى من قبل الورثة أو وكيل التفليسة أو المصفي خلال ستة أشهر على الأكثر من تاريخ تبليغهم من قبل الدائرة وفق أحكام هذا القانون برقم الدعوى واسم المحكمة التي تنظرها والإشعار المتضمن نتيجة القرار المطعون فيه، وفي حال عدم متابعة السير في القضية على الوجه المذكور يكتسب القرار المطعون فيه الدرجة القطعية.\nك- باستثناء الدعاوى المعدة للفصل، تحال جميع الدعاوى التي تكون الدائرة طرفا فيها المنظورة بتاريخ سريان أحكام هذا القانون:\n١- لدى محكمة الجمارك البدائية إلى محكمة البداية الضريبية لمتابعة السير فيها من النقطة التي وصلت إليها.\n٢- لدى محكمة الجمارك الاستئنافية إلى محكمة الاستئناف الضريبية لمتابعة السير فيها من النقطة التي وصلت إليها.\nل- تختص محكمة البداية الضريبية ومحكمة الاستئناف الضريبية بالنظر في جميع الدعاوى المقامة بعد نفاذ أحكام هذا القانون التي تكون الدائرة طرفاً فيها والتي كانت تدخل قبل نفاذه ضمن اختصاص محكمة الجمارك البدائية ومحكمة الجمارك الاستئنافية على التوالي.","title":"اختصاص المحاكم الضريبية وإجراءات الدعوى","memo":"⭐ محكمة البداية الضريبية تختص بجميع الدعاوى الناشئة عن القانون مهما كانت قيمتها وطبيعتها؛ أحكامها تستأنف لدى محكمة الاستئناف الضريبية مرافعة، ثم التمييز\n⭐ الرسم يستوفى عن كل فترة ضريبية مستقلاً؛ يبين المكلف المبلغ المسلم به ويرفق إيصال دفعه وإلا ترد الدعوى\n⭐ عبء إثبات أن المبالغ باهظة على المكلف؛ إذا أسقطت الدعوى ولم تجدد يصبح القرار قطعياً بعد ٣٠ يوماً من التبليغ، ولا تجدد للسبب نفسه أكثر من مرتين\n⭐ وفاة المكلف أو إفلاسه أو تصفيته: متابعة الدعوى خلال ٦ أشهر على الأكثر من التبليغ وإلا اكتسب القرار الدرجة القطعية","qs":[{"q":"تكون الأحكام الصادرة عن محكمة البداية الضريبية قابلة للطعن لدى:","o":["محكمة الاستئناف الضريبية ويتم النظر فيها مرافعة","محكمة التمييز مباشرة","محكمة العدل العليا","هيئة الاعتراض"],"a":0},{"q":"لم يرفق المكلف بلائحة دعواه إيصالاً بدفع المبلغ الذي يسلم به، فإن المحكمة:","o":["ترد الدعوى","تمهله ثلاثين يوماً لدفعه","تنظر الدعوى وتحسم المبلغ من الحكم","تحيل الدعوى إلى هيئة الاعتراض"],"a":0},{"q":"يقع عبء إقامة الدليل على أن المبالغ التي حددها القرار المطعون فيه باهظة على:","o":["المكلف","الدائرة","النيابة العامة الضريبية","المدقق الذي أصدر القرار"],"a":0},{"q":"توفي مكلف أثناء نظر دعواه أمام محكمة البداية الضريبية، فيجب على الورثة متابعة السير في الدعوى خلال:","o":["ستة أشهر على الأكثر من تاريخ تبليغهم من قبل الدائرة","ثلاثين يوماً من تاريخ الوفاة","سنة من تاريخ تبليغهم من قبل الدائرة","ثلاثة أشهر من تاريخ الوفاة"],"a":0}]},{"n":"58","chapter":"","notes":[],"source":"أ- تتولى النيابة العامة الضريبية تمثيل الدائرة في جميع القضايا التي تكون طرفاً فيها أمام المحكمة وفق الاختصاصات والصلاحيات المحددة لكل من اعضائها.\nب-تقام الدعاوى في الجرائم المنصوص عليها في هذا القانون بناءً على طلب المدير أو رئيس النيابة العامة.\nج-\n١- على الرغم مما ورد في أي قانون آخر، تعتبر خدمة كل من أشغل إحدى وظائف النيابة العامة الضريبية خدمة قضائية لغايات قانون استقلال القضاء وقانون نقابة المحامين النظاميين شريطة ألا تقل هذه الخدمة عن ثلاث سنوات متتالية.\n٢- تعتبر خدمة المدعي العام الذي مارس وظيفة النيابة العامة في القضايا المتعلقة بالضريبة امام محكمة الجمارك البدائية ومحكمة الجمارك الاستئنافية ومحكمة التمييز من ضمن خدمة المدعي العام الضريبي لغايات البند (١) من هذه الفقرة.","title":"النيابة العامة الضريبية","memo":"⭐ النيابة العامة الضريبية تمثل الدائرة في جميع القضايا أمام المحكمة\n⭐ دعاوى الجرائم تقام بناءً على طلب المدير أو رئيس النيابة العامة\n⭐ خدمة النيابة العامة الضريبية تعتبر خدمة قضائية لغايات قانوني استقلال القضاء ونقابة المحامين بشرط ألا تقل عن ٣ سنوات متتالية","qs":[{"q":"تتولى تمثيل الدائرة في جميع القضايا التي تكون طرفاً فيها أمام المحكمة:","o":["النيابة العامة الضريبية","إدارة قضايا الدولة","المستشار القانوني للدائرة","هيئة الاعتراض"],"a":0},{"q":"تقام الدعاوى في الجرائم المنصوص عليها في قانون الضريبة العامة على المبيعات بناءً على طلب:","o":["المدير أو رئيس النيابة العامة","الوزير أو مجلس الوزراء","هيئة الاعتراض","المدقق المختص"],"a":0},{"q":"تعتبر خدمة من أشغل إحدى وظائف النيابة العامة الضريبية خدمة قضائية لغايات قانون استقلال القضاء شريطة ألا تقل عن:","o":["ثلاث سنوات متتالية","سنتين متتاليتين","خمس سنوات متتالية","أربع سنوات متتالية"],"a":0}]},{"n":"59","chapter":"","notes":[],"source":"تطبق محكمة البداية الضريبية ومحكمة الاستئناف الضريبية الأصول المنصوص عليها في قانون أصول المحاكمات الجزائية بالقدر الذي لا تتعارض فيه مع أحكام هذا القانون، كما تطبق الأصول المنصوص عليها في قانون أصول المحاكمات المدنية بالقدر الذي لا تتعارض فيه مع أحكام هذا القانون والأنظمة الصادرة بمقتضاه.","title":"الأصول المطبقة أمام المحاكم الضريبية","memo":"⭐ تطبق محكمتا البداية والاستئناف الضريبيتان أصول المحاكمات الجزائية وأصول المحاكمات المدنية بالقدر الذي لا يتعارض مع أحكام هذا القانون","qs":[{"q":"تطبق محكمة البداية الضريبية ومحكمة الاستئناف الضريبية الأصول المنصوص عليها في قانوني أصول المحاكمات الجزائية والمدنية:","o":["بالقدر الذي لا تتعارض فيه مع أحكام قانون الضريبة العامة على المبيعات","بشكل مطلق ولو تعارضت مع أحكام قانون الضريبة","في القضايا الجزائية فقط","بعد موافقة المدير في كل قضية"],"a":0},{"q":"القانونان الإجرائيان اللذان تطبق المحاكم الضريبية أصولهما بالقدر الذي لا يتعارض مع قانون الضريبة العامة على المبيعات هما:","o":["قانون أصول المحاكمات الجزائية وقانون أصول المحاكمات المدنية","قانون تحصيل الأموال الأميرية وقانون الجمارك","قانون استقلال القضاء وقانون نقابة المحامين","قانون محاكم الصلح وقانون التنفيذ"],"a":0}]},{"n":"60","chapter":"","notes":[],"source":"يجوز للمكلف المثول بشخصه أمام المحكمة وتوقيع اللوائح والاستدعاءات المقدمة إليها إذا كان قاضياً عاملاً أو سابقاً أو محامياً مزاولاً أو غير مزاول وغيرهم من الأشخاص المعفيين من التدريب بموجب قانون نقابة المحامين النظاميين.","title":"مثول المكلف بشخصه أمام المحكمة","memo":"⭐ يجوز للمكلف المثول بشخصه وتوقيع اللوائح إذا كان قاضياً عاملاً أو سابقاً، أو محامياً مزاولاً أو غير مزاول، أو من المعفيين من التدريب وفق قانون نقابة المحامين","qs":[{"q":"أي من الأشخاص التالين يجوز له بصفته مكلفاً المثول بشخصه أمام المحكمة وتوقيع اللوائح دون محامٍ:","o":["محامٍ غير مزاول","محاسب قانوني مرخص","موظف سابق في الدائرة","مدقق حسابات داخلي"],"a":0},{"q":"يجوز للمكلف المثول بشخصه أمام المحكمة وتوقيع اللوائح إذا كان من الأشخاص المعفيين من التدريب بموجب:","o":["قانون نقابة المحامين النظاميين","قانون استقلال القضاء","قانون تنظيم مهنة المحاسبة القانونية","قانون أصول المحاكمات المدنية"],"a":0}]},{"n":"61","chapter":"","notes":[],"source":"تقدم لائحة الدعوى إلى محكمة البداية الضريبية أو بواسطة رئيس محكمة البداية التي يقيم المكلف في منطقة اختصاصها، وفي هذه الحالة تدفع الرسوم إلى صندوق المحكمة التي قُدمت لائحة الدعوى بواسطة رئيسها، وترسل هذه المحكمة اللائحة ومرفقاتها إلى محكمة البداية الضريبية خلال عشرة أيام من تاريخ تقديمها.","title":"تقديم لائحة الدعوى","memo":"⭐ تقدم اللائحة إلى محكمة البداية الضريبية أو بواسطة رئيس محكمة البداية التي يقيم المكلف في منطقة اختصاصها\n⭐ في هذه الحالة تدفع الرسوم لصندوق تلك المحكمة، وترسل اللائحة ومرفقاتها للمحكمة الضريبية خلال ١٠ أيام من تقديمها","qs":[{"q":"إذا قدمت لائحة الدعوى بواسطة رئيس محكمة البداية التي يقيم المكلف في منطقة اختصاصها، فإن هذه المحكمة ترسل اللائحة إلى محكمة البداية الضريبية خلال:","o":["عشرة أيام من تاريخ تقديمها","ثلاثين يوماً من تاريخ تقديمها","سبعة أيام من تاريخ تقديمها","خمسة عشر يوماً من تاريخ تقديمها"],"a":0},{"q":"قدم مكلف يقيم في إربد لائحة دعواه بواسطة رئيس محكمة بداية إربد، فإن الرسوم تدفع إلى:","o":["صندوق محكمة بداية إربد","صندوق محكمة البداية الضريبية","صندوق الدائرة","صندوق محكمة الاستئناف الضريبية"],"a":0}]},{"n":"62","chapter":"","notes":[],"source":"يعتمد عنوان المسجل الوارد في طلب تسجيله أو في آخر إقرار ضريبي مقدم للدائرة لغايات تبليغه وفق أحكام هذا القانون، ولا يعتد بأي تغيير يطرأ على هذا العنوان ما لم يقم المسجل بتبليغ الدائرة خلال ثلاثين يوماً من تاريخ هذا التغيير وذلك بموجب كتاب خطي مؤشر عليه من الدائرة.","title":"عنوان المسجل المعتمد للتبليغ","memo":"⭐ يعتمد العنوان الوارد في طلب التسجيل أو في آخر إقرار ضريبي مقدم\n⭐ لا يعتد بتغيير العنوان ما لم يبلغ المسجل الدائرة خلال ٣٠ يوماً بكتاب خطي مؤشر عليه من الدائرة","qs":[{"q":"يعتمد لغايات تبليغ المسجل عنوانه الوارد في:","o":["طلب تسجيله أو آخر إقرار ضريبي مقدم للدائرة","سجله التجاري لدى وزارة الصناعة والتجارة","رخصة المهن الصادرة عن البلدية","هويته الشخصية"],"a":0},{"q":"غيّر مسجل عنوانه ولم يبلغ الدائرة بذلك خلال المدة القانونية، فإن:","o":["التغيير لا يعتد به ويبقى العنوان السابق معتمداً للتبليغ","التبليغ على العنوان السابق يعتبر باطلاً","الدائرة تلزم بالبحث عن العنوان الجديد","التبليغ يتم بالنشر حكماً"],"a":0},{"q":"يجب على المسجل تبليغ الدائرة بتغيير عنوانه خلال:","o":["ثلاثين يوماً من تاريخ التغيير بكتاب خطي مؤشر عليه من الدائرة","عشرة أيام من تاريخ التغيير","ستين يوماً من تاريخ التغيير","موعد تقديم الإقرار الضريبي التالي"],"a":0}]},{"n":"63","chapter":"","notes":[],"source":"أ-\n١- تتولى الدائرة تبليغ المكلف بأي مطالبة أو إشعار أو قرار أو مذكرة أو كتاب صادر عنها وفق أحكام هذا القانون بإرساله بالبريد المسجل أو بواسطة الشركة المرخصة المعتمدة وذلك على العنوان المعتمد لدى الدائرة وفق أحكام المادة (٦٢) من هذا القانون.\n٢- إذا تعذر تبليغ المكلف وفق أحكام البند (١) من هذه الفقرة فيجوز إجراء التبليغ بالنشر لمرتين في صحيفتين يوميتين محليتين، ويعتبر التبليغ في هذه الحالة قانونيا ومنتجا لجميع آثاره.\nب-\n١- إذا لم يتوفر لدى الدائرة عنوان للمكلف وفق أحكام المادة (٦٢) من هذا القانون فللمدير إجراء التبليغ بالنشر لمرة واحدة على الأقل في صحيفتين يوميتين محليتين.\n٢- للمدقق أو هيئة الاعتراض بناء على طلب المكلف المستند إلى أسباب مبررة عدم اعتبار النشر الوارد في البند (١) من هذه الفقرة بمثابة تبليغ، وفي هذه الحالة يسري ميعاد جديد اعتباراً من تاريخ تبليغ المكلف قرار المدقق أو الهيئة بقبول الطلب.\nج- في جميع الأحوال يجوز للدائرة تبليغ المكلف بالذات أو بواسطة شخص مفوض عنه.\nد- يعتبر التبليغ قانونياً بعد مرور عشرة أيام على إرساله في البريد المسجل أو بواسطة الشركة المرخصة المعتمدة إذا كان المكلف مقيماً داخل المملكة أو بعد مرور ثلاثين يوماً على إرساله في البريد المسجل أو بواسطة الشركة المرخصة المعتمدة إذا كان مقيما خارجها ويكفي لإثبات التبليغ تقديم الدليل على أن الرسالة المحتوية على المادة المراد تبليغها قد عنونت وأرسلت بالبريد المسجل أو بواسطة الشركة المرخصة المعتمدة على العنوان الوارد في المادة (٦٢) من هذا القانون.\nه- لا يحتسب اليوم الذي تم فيه التبليغ لغايات احتساب المدد المنصوص عليها في هذا القانون.","title":"التبليغ وأحكامه","memo":"⭐ التبليغ بالبريد المسجل أو الشركة المرخصة المعتمدة على العنوان المعتمد (م٦٢)؛ إن تعذر فبالنشر لمرتين في صحيفتين يوميتين محليتين\n⭐ عدم توفر عنوان: للمدير التبليغ بالنشر مرة واحدة على الأقل في صحيفتين يوميتين محليتين\n⭐ يعتبر التبليغ قانونياً بعد ١٠ أيام من الإرسال للمقيم داخل المملكة و٣٠ يوماً للمقيم خارجها\n⭐ لا يحتسب يوم التبليغ عند احتساب المدد","qs":[{"q":"إذا تعذر تبليغ المكلف بالبريد المسجل على العنوان المعتمد لدى الدائرة، فيجوز إجراء التبليغ:","o":["بالنشر لمرتين في صحيفتين يوميتين محليتين","بالنشر لمرة واحدة في صحيفة يومية واحدة","بالإلصاق على باب مقر المكلف","بالنشر على الموقع الإلكتروني للدائرة فقط"],"a":0},{"q":"أرسلت الدائرة إشعاراً بالبريد المسجل إلى مكلف مقيم داخل المملكة، يعتبر التبليغ قانونياً بعد مرور:","o":["عشرة أيام على إرساله","ثلاثين يوماً على إرساله","سبعة أيام على إرساله","خمسة عشر يوماً على إرساله"],"a":0},{"q":"يعتبر التبليغ المرسل بالبريد المسجل إلى مكلف مقيم خارج المملكة قانونياً بعد مرور:","o":["ثلاثين يوماً على إرساله","عشرة أيام على إرساله","ستين يوماً على إرساله","تسعين يوماً على إرساله"],"a":0},{"q":"الجهة التي يجوز لها بناءً على طلب المكلف المستند إلى أسباب مبررة عدم اعتبار النشر (عند عدم توفر عنوان) بمثابة تبليغ هي:","o":["المدقق أو هيئة الاعتراض","الوزير","محكمة البداية الضريبية","مجلس الوزراء"],"a":0}]},{"n":"64","chapter":"","notes":[],"source":"على كل مصف لأي شركة أو تركة أو وكيل تفليسة أو أي شخص مسؤول عن أي تصفية مشابهة أو تسوية من أي نوع أن يبلغ المدير خطياً ببدء إجراءات التصفية أو بشهر الإفلاس أو أي إجراءات أخرى حسب مقتضى الحال لبيان وتثبيت المبالغ المستحقة للدائرة وفي حال التخلف عن ذلك يعتبر كل من أولئك الأشخاص مسؤولاً مسؤولية مباشرة وشخصية عن دفع تلك المبالغ وفق أحكام هذا القانون على ألا يعفي هذا الحكم الورثة من دفع تلك المبالغ من أي أموال منقولة أو غير منقولة آلت إليهم من التركة.","title":"التزامات المصفي ووكيل التفليسة","memo":"⭐ على المصفي أو وكيل التفليسة أو المسؤول عن أي تصفية أو تسوية تبليغ المدير خطياً ببدء الإجراءات\n⭐ عند التخلف يصبح مسؤولاً مسؤولية مباشرة وشخصية عن دفع المبالغ المستحقة\n⭐ لا يعفى الورثة من الدفع من الأموال التي آلت إليهم من التركة","qs":[{"q":"يجب على مصفي الشركة أو وكيل التفليسة تبليغ المدير ببدء إجراءات التصفية أو شهر الإفلاس، وفي حال التخلف عن ذلك:","o":["يعتبر مسؤولاً مسؤولية مباشرة وشخصية عن دفع المبالغ المستحقة للدائرة","يعاقب بالحبس مدة لا تزيد على سنة فقط","تسقط حقوق الدائرة في تلك المبالغ","تبطل إجراءات التصفية حكماً"],"a":0},{"q":"تخلف مصفي تركة عن تبليغ المدير ببدء إجراءات التصفية، فإن الورثة:","o":["لا يعفون من دفع المبالغ المستحقة من الأموال التي آلت إليهم من التركة","يعفون من دفع المبالغ لانتقال المسؤولية إلى المصفي","يدفعون المبالغ من أموالهم الخاصة دون حد","يعفون من غرامات التأخير فقط"],"a":0}]},{"n":"65","chapter":"","notes":[],"source":"أ- للمدير او لأي موظف مفوض من قبله خطياً طلب المعلومات الضرورية لتنفيذ أحكام هذا القانون من أي شخص أو جهة كانت ويشترط في ذلك أن لا يلزم موظفو الحكومة والمؤسسات الرسمية والعامة والبلديات على إفشاء أي تفاصيل يكونون ملزمين بحكم القانون بالمحافظة عليها وكتمانها كما يشترط عدم المساس بسرية العمليات المصرفية ويعتبر كل من يمتنع عن إعطاء هذه المعلومات أنه ارتكب جرما يعاقب عليه بالعقوبات المنصوص عليها في المادة (٣١) من هذا القانون.\nب-يعتبر المدير وموظفو الدائرة المفوضون خطياً من قبله أثناء قيامهم بأعمالهم من رجال الضابطة العدلية في حدود اختصاصهم وعلى السلطات الرسمية أن تقدم لموظفي الدائرة المساعدة اللازمة لتمكينهم من القيام بأعمالهم وفي الحالات التي تستدعي ذلك ويكون التفويض في كل حالة على حده.\nج- للمدير أو من يفوضه خطياً من موظفي الدائرة وله صفة الضابطة العدلية في الحالات التي تستدعي ذلك تولي أعمال الرقابة على أماكن الإدارة والانتاج والبيع للسلع والخدمات الخاضعة للضريبة والدخول إلى أي مكان يجري ممارسة عمل فيه وأن يفحص البضائع المخزونة والنقد والآلات والماكنات والدفاتر والسجلات والحسابات والقيود والمستندات الأخرى المتعلقة بذلك العمل، كما يجوز له ضبط هذه الدفاتر والسجلات والحسابات والقيود والمستندات والاحتفاظ بها لمدة لا تزيد على ثلاثين يوماً من تاريخ ضبطها إذا اقتنع أن ذلك ضروري لتنفيذ احكام هذا القانون ويترتب على المسؤولين في المؤسسات والمصالح المعنية تسهيل مهمته ، كما يجوز له أخذ عينات من السلع لغايات التحليل والاستعانة بأهل الخبرة والاختصاص للقيام بأعماله.\nد- لا يجوز تفتيش بيوت السكن إلا وفق الإجراءات المنصوص عليها في قانون أصول المحاكمات الجزائية النافذ.","title":"طلب المعلومات وصفة الضابطة العدلية","memo":"⭐ للمدير أو موظف مفوض خطياً طلب المعلومات من أي شخص، مع عدم إلزام موظفي الحكومة بإفشاء ما يلزمون بكتمانه وعدم المساس بسرية العمليات المصرفية؛ الممتنع يعاقب بعقوبات المادة (٣١)\n⭐ المدير والموظفون المفوضون خطياً من رجال الضابطة العدلية، والتفويض في كل حالة على حدة\n⭐ ضبط الدفاتر والاحتفاظ بها مدة لا تزيد على ٣٠ يوماً من تاريخ ضبطها\n⭐ لا يجوز تفتيش بيوت السكن إلا وفق قانون أصول المحاكمات الجزائية","qs":[{"q":"يجوز لموظف الدائرة الذي له صفة الضابطة العدلية ضبط الدفاتر والسجلات والاحتفاظ بها لمدة لا تزيد على:","o":["ثلاثين يوماً من تاريخ ضبطها","عشرة أيام من تاريخ ضبطها","تسعين يوماً من تاريخ ضبطها","ستة أشهر من تاريخ ضبطها"],"a":0},{"q":"يعاقب الشخص الذي يمتنع عن إعطاء المعلومات الضرورية التي يطلبها المدير لتنفيذ أحكام القانون بالعقوبات المنصوص عليها في المادة:","o":["(٣١) من القانون","(٦٦) من القانون","(٦٧) من القانون","(٥١) من القانون"],"a":0},{"q":"أي مما يلي لا يجوز إلا وفق الإجراءات المنصوص عليها في قانون أصول المحاكمات الجزائية:","o":["تفتيش بيوت السكن","فحص البضائع المخزونة في مكان العمل","أخذ عينات من السلع لغايات التحليل","الدخول إلى أماكن الإنتاج والبيع"],"a":0},{"q":"عند طلب المدير المعلومات الضرورية لتنفيذ أحكام القانون، يشترط:","o":["عدم المساس بسرية العمليات المصرفية","الحصول على إذن مسبق من المحكمة","موافقة الوزير على كل طلب","أن يكون الطلب موجهاً إلى المسجلين فقط"],"a":0}]},{"n":"66","chapter":"","notes":[],"source":"أ- يترتب على كل من يضطلع بواجب رسمي لتنفيذ أحكام هذا القانون:\n١- أن يعتبر المستندات والسجلات والمعلومات والإقرارات الضريبية وقرارات التدقيق والتقدير ونسخها التي يطلع عليها المتعلقة بنشاط أي شخص أو مفردات ذلك النشاط أنها سرية ومكتومة وأن يتداول بها على هذا الأساس.\n٢- أن يقدم ويوقع تصريحاً للمحافظة على الأسرار حسب الصيغة التي يضعها المدير.\n٣- أن يقدم إلى المدير عند تعيينه كشفاً بأمواله المنقولة وغير المنقولة ومصادر دخله وأموال زوجته وأولاده القاصرين كما يترتب عليه في مطلع كل سنة لاحقة أن يبين أي زيادة طرأت على تلك الاموال.\nب-لا يكلف الشخص المضطلع بتنفيذ أي من أحكام هذا القانون بأن يبرز أي مستند أو إقرار ضريبي أو قرار تقدير أو قرار تدقيق أو نسخا عنها في أي محكمة غير المحكمة المختصة أو بأن يفشي أمام أي محكمة أو بأن يبلغها أي أمر أو شيء مما يكون قد اطلع عليه في سياق اضطلاعه بواجباته بمقتضى هذا القانون إلا ما كان ضروريا لتنفيذ أحكامه حسبما يقرره المدير في كل حالة تنشأ بمقتضى هذه الفقرة أو من أجل تعقب أي جرم.\nج- يعاقب بغرامة لا تقل عن (١٠٠) مائة دينار ولا تزيد على (٥٠٠) خمسمائة دينار أو بالحبس مدة لا تزيد على سنة أو بكلتا هاتين العقوبتين كل من وجدت في حيازته أو تحت رقابته أي مستندات أو إقرارات ضريبية أو قرارات تقدير أو قرارات تدقيق أو نسخها تتعلق بنشاط أي شخص أو مفردات هذا النشاط وبلغ أو حاول تبليغ تلك المعلومات أو أي شيء ورد في أي منها في أي وقت لأي شخص غير الشخص الذي يخوله القانون تبليغها إليه او لأي غاية اخرى خلاف الغايات الواردة في هذا القانون.","title":"السرية والتزامات موظفي الدائرة","memo":"⭐ على كل من ينفذ القانون اعتبار المستندات والإقرارات والقرارات سرية، وتوقيع تصريح المحافظة على الأسرار بالصيغة التي يضعها المدير\n⭐ تقديم كشف بأمواله وأموال زوجته وأولاده القاصرين عند التعيين، وبيان أي زيادة في مطلع كل سنة\n⭐ عقوبة إفشاء المعلومات: غرامة (١٠٠-٥٠٠) دينار أو الحبس مدة لا تزيد على سنة أو كلتاهما","qs":[{"q":"عقوبة من بلّغ أو حاول تبليغ معلومات الإقرارات الضريبية لشخص غير مخول قانوناً:","o":["غرامة لا تقل عن (١٠٠) دينار ولا تزيد على (٥٠٠) دينار أو الحبس مدة لا تزيد على سنة أو كلتا العقوبتين","غرامة لا تقل عن (٥٠٠) دينار ولا تزيد على (١٠٠٠) دينار فقط","الحبس مدة لا تقل عن سنة ولا تزيد على ثلاث سنوات","غرامة لا تقل عن (١٠٠٠) دينار ولا تزيد على (٥٠٠٠) دينار"],"a":0},{"q":"يترتب على من يضطلع بواجب رسمي لتنفيذ أحكام القانون أن يقدم إلى المدير عند تعيينه كشفاً بـ:","o":["أمواله المنقولة وغير المنقولة ومصادر دخله وأموال زوجته وأولاده القاصرين","أسماء أقاربه حتى الدرجة الرابعة","المكلفين الذين تربطه بهم علاقة عمل سابقة","مؤهلاته العلمية وخبراته العملية فقط"],"a":0},{"q":"صيغة التصريح الذي يقدمه ويوقعه الموظف للمحافظة على الأسرار يضعها:","o":["المدير","الوزير","مجلس الوزراء","ديوان الخدمة المدنية"],"a":0}]},{"n":"67","chapter":"","notes":[],"source":"يتحمل المحاسب القانوني المسؤولية عن إصدار البيانات المالية أو المصادقة على بيانات مالية غير مطابقة للواقع بشكل جوهري أو تخالف أحكام هذا القانون أو معايير المحاسبة الدولية والقوانين والأنظمة النافذة المفعول سواء كان ذلك ناجماً عن خطأ مقصود أو أي عمل جرمي أو عن إهمال جسيم، وفي هذه الحالة يعتبر المحاسب القانوني أنه ارتكب جرماً ويعاقب عليه بالعقوبة المنصوص عليها في المادة (٣١) من هذا القانون.","title":"مسؤولية المحاسب القانوني","memo":"⭐ يتحمل المحاسب القانوني المسؤولية عن إصدار أو المصادقة على بيانات مالية غير مطابقة للواقع بشكل جوهري أو مخالفة للقانون أو لمعايير المحاسبة الدولية\n⭐ سواء كان ذلك عن خطأ مقصود أو عمل جرمي أو إهمال جسيم، ويعاقب بعقوبة المادة (٣١)","qs":[{"q":"يعتبر المحاسب القانوني مرتكباً لجرم إذا صادق على بيانات مالية غير مطابقة للواقع بشكل جوهري نتيجة:","o":["إهمال جسيم","خطأ يسير غير مقصود","اختلاف في التقدير المهني المعقول","تأخر المكلف في تزويده بالمستندات"],"a":0},{"q":"يعاقب المحاسب القانوني الذي يصدر بيانات مالية تخالف معايير المحاسبة الدولية عن خطأ مقصود بالعقوبة المنصوص عليها في المادة:","o":["(٣١) من القانون","(٦٦) من القانون","(٥١) من القانون","(٦٩) من القانون"],"a":0}]},{"n":"68","chapter":"","notes":[],"source":"أ- لا يحول تطبيق أحكام هذا القانون دون تطبيق أي عقوبة أشد وَرَد النص عليها في أي تشريع آخر.\nب-تعتبر جميع الغرامات الناجمة عن ارتكاب أي جريمة خلافا لأحكام هذا القانون تعويضا مدنياً للدائرة ولا تشملها أحكام قوانين العفو العام.","title":"العقوبة الأشد والغرامات كتعويض مدني","memo":"⭐ لا يحول تطبيق القانون دون تطبيق عقوبة أشد في تشريع آخر\n⭐ جميع الغرامات الناجمة عن الجرائم تعتبر تعويضاً مدنياً للدائرة ولا تشملها قوانين العفو العام","qs":[{"q":"صدر قانون عفو عام بعد الحكم على مكلف بغرامات لارتكابه جريمة خلافاً لقانون الضريبة العامة على المبيعات، فإن هذه الغرامات:","o":["لا يشملها العفو العام لأنها تعتبر تعويضاً مدنياً للدائرة","تسقط بالكامل بموجب العفو العام","يسقط نصفها بموجب العفو العام","تسقط إذا قدم المكلف طلباً بذلك خلال ثلاثين يوماً"],"a":0},{"q":"إذا نص تشريع آخر على عقوبة أشد للفعل المعاقب عليه في قانون الضريبة العامة على المبيعات، فإن:","o":["تطبيق أحكام قانون الضريبة لا يحول دون تطبيق العقوبة الأشد","تطبق عقوبة قانون الضريبة حصراً","تطبق العقوبة الأخف دائماً","يحال الأمر إلى الوزير لاختيار العقوبة"],"a":0}]},{"n":"69","chapter":"","notes":[],"source":"أ- للوزير بتنسيب من المدير بناءً على توصية لجنة مشكلة لهذه الغاية منع أي شخص طبيعي من مراجعة الدائرة في أي قضية أو عمل خلاف قضيته الشخصية إذا اقتنع أنه خلال مراجعاته وتعامله مع الدائرة ارتكب ما من شأنه تعطيل سير العمل وفق الأصول أو التحايل على هذا القانون، وله أن يقرر عدم قبول الدائرة للحسابات التي يعدها أو يدققها ذلك الشخص إذا كان محاسباً أو محاسبا قانونيا وذلك للمدة التي يراها مناسبة.\nب-يحظر على الموظف الذي انتهت خدمته في الدائرة مراجعة الدائرة لمدة سنة في أي معاملة أو قضية خلاف المعاملة أو القضية الخاصة به إلا بعد الحصول على موافقة خطية مسبقة من المدير.","title":"منع مراجعة الدائرة","memo":"⭐ للوزير بتنسيب المدير بناءً على توصية لجنة منع أي شخص طبيعي من مراجعة الدائرة في غير قضيته الشخصية إذا عطل سير العمل أو تحايل على القانون، وعدم قبول حساباته إن كان محاسباً\n⭐ يحظر على الموظف الذي انتهت خدمته مراجعة الدائرة لمدة سنة في غير معاملته الخاصة إلا بموافقة خطية مسبقة من المدير","qs":[{"q":"الجهة المختصة بمنع شخص طبيعي من مراجعة الدائرة في غير قضيته الشخصية إذا ثبت تحايله على القانون هي:","o":["الوزير بتنسيب من المدير بناءً على توصية لجنة مشكلة لهذه الغاية","المدير بناءً على توصية هيئة الاعتراض","مجلس الوزراء بتنسيب من الوزير","محكمة البداية الضريبية بناءً على طلب النيابة العامة الضريبية"],"a":0},{"q":"يحظر على الموظف الذي انتهت خدمته في الدائرة مراجعتها في معاملة غير معاملته الخاصة لمدة:","o":["سنة، إلا بموافقة خطية مسبقة من المدير","سنتين، إلا بموافقة الوزير","ثلاث سنوات دون أي استثناء","ستة أشهر، إلا بموافقة الوزير"],"a":0},{"q":"محاسب قانوني ثبت أنه عطل سير العمل في الدائرة خلال مراجعاته، فيجوز للوزير وفق الإجراءات القانونية:","o":["أن يقرر عدم قبول الدائرة للحسابات التي يعدها أو يدققها للمدة التي يراها مناسبة","أن يلغي ترخيصه لمزاولة المهنة نهائياً","أن يفرض عليه غرامة مالية مقدارها (٥٠٠) دينار","أن يحيله إلى هيئة الاعتراض"],"a":0}]},{"n":"70","chapter":"","notes":[],"source":"للمدير بناء على تنسيب أي من أعضاء النيابة العامة الضريبية إجراء المصالحة في أي قضية أقامها المكلف لدى المحكمة بموجب هذا القانون وذلك قبل صدور الحكم القطعي فيها وعلى المحكمة تصديق هذه المصالحة واعتبارها حكما قطعياً صادراً عنها.","title":"المصالحة في القضايا","memo":"⭐ للمدير بتنسيب أي من أعضاء النيابة العامة الضريبية إجراء المصالحة في قضية أقامها المكلف قبل صدور الحكم القطعي\n⭐ على المحكمة تصديق المصالحة واعتبارها حكماً قطعياً صادراً عنها","qs":[{"q":"يجوز إجراء المصالحة في أي قضية أقامها المكلف لدى المحكمة من قبل:","o":["المدير بناءً على تنسيب أي من أعضاء النيابة العامة الضريبية","الوزير بناءً على تنسيب المدير","رئيس النيابة العامة الضريبية منفرداً","هيئة الاعتراض بناءً على طلب المكلف"],"a":0},{"q":"بعد إجراء المصالحة في القضية التي أقامها المكلف وفق القانون، فإن على المحكمة:","o":["تصديق المصالحة واعتبارها حكماً قطعياً صادراً عنها","إعادة القضية إلى هيئة الاعتراض","النظر في موضوع الدعوى رغم المصالحة","رفعها إلى محكمة الاستئناف الضريبية للمصادقة"],"a":0}]},{"n":"71","chapter":"","notes":[],"source":"يجوز للمدير أو الموظف المفوض من قبله أو المدقق حسب مقتضى الحال وفي اي وقت أن يصحح من تلقاء ذاته أو بناء على طلب المكلف الأخطاء الكتابية والحسابية التي تقع في القرارات والإشعارات والمذكرات عن طريق السهو العرضي ولا تكون إجراءات التصحيح خاضعة للطعن.","title":"تصحيح الأخطاء الكتابية والحسابية","memo":"⭐ للمدير أو الموظف المفوض أو المدقق في أي وقت تصحيح الأخطاء الكتابية والحسابية الواقعة سهواً، من تلقاء ذاته أو بطلب المكلف\n⭐ إجراءات التصحيح غير خاضعة للطعن","qs":[{"q":"إجراءات تصحيح الأخطاء الكتابية والحسابية التي تقع في القرارات والإشعارات عن طريق السهو العرضي:","o":["غير خاضعة للطعن","قابلة للاعتراض لدى هيئة الاعتراض خلال ثلاثين يوماً","قابلة للطعن لدى محكمة البداية الضريبية","تخضع لمصادقة الوزير"],"a":0},{"q":"يجوز تصحيح الأخطاء الكتابية والحسابية الواقعة في القرارات عن طريق السهو العرضي:","o":["في أي وقت من تلقاء ذاته أو بناءً على طلب المكلف","خلال أربع سنوات من تاريخ القرار فقط","بناءً على طلب المكلف فقط","بعد موافقة المحكمة"],"a":0}]},{"n":"72","chapter":"","notes":[],"source":"أ- للوزير أن يفوض خطيا أي من صلاحياته المنصوص عليها في هذا القانون للمدير.\nب-للمدير أن يفوض أي من صلاحياته المنصوص عليها في هذا القانون إلى أي موظف في الدائرة على أن يكون التفويض خطياً ومحدداً.","title":"تفويض الصلاحيات","memo":"⭐ للوزير تفويض أي من صلاحياته للمدير خطياً\n⭐ للمدير تفويض أي من صلاحياته لأي موظف في الدائرة على أن يكون التفويض خطياً ومحدداً","qs":[{"q":"يجوز للوزير أن يفوض خطياً أياً من صلاحياته المنصوص عليها في القانون إلى:","o":["المدير","أي موظف في الدائرة","هيئة الاعتراض","أمين عام وزارة المالية"],"a":0},{"q":"يشترط في تفويض المدير لأي من صلاحياته إلى موظف في الدائرة أن يكون:","o":["خطياً ومحدداً","بموافقة مجلس الوزراء","منشوراً في الجريدة الرسمية","لمدة لا تزيد على سنة"],"a":0}]},{"n":"73","chapter":"","notes":[],"source":"ما لم ينص هذا القانون على خلاف ذلك تحسب المواعيد المعينة بالشهر أو السنة بالتقويم الميلادي وفي حال صادف آخر الميعاد عطلة رسمية امتد إلى أول يوم عمل بعدها.","title":"احتساب المواعيد","memo":"⭐ تحسب المواعيد المعينة بالشهر أو السنة بالتقويم الميلادي ما لم ينص القانون على خلاف ذلك\n⭐ إذا صادف آخر الميعاد عطلة رسمية امتد إلى أول يوم عمل بعدها","qs":[{"q":"تحسب المواعيد المعينة بالشهر أو السنة في قانون الضريبة العامة على المبيعات ما لم ينص على خلاف ذلك:","o":["بالتقويم الميلادي","بالتقويم الهجري","حسب أيام العمل الرسمي فقط","حسب السنة المالية للمكلف"],"a":0},{"q":"صادف آخر يوم في ميعاد الاعتراض عطلة رسمية، فإن الميعاد:","o":["يمتد إلى أول يوم عمل بعدها","ينتهي في يوم العطلة","ينتهي في آخر يوم عمل قبلها","يمتد سبعة أيام إضافية"],"a":0}]},{"n":"74","chapter":"","notes":[],"source":"أ- تتولى دائرة الجمارك تحصيل الضريبة عن السلع والخدمات المستوردة وتوريدها للخزينة.\nب-إذا قامت دائرة الجمارك بضبط أي مخالفة أو جرم خلافاً لأحكام هذا القانون فيتم إحالته إلى الدائرة لاتخاذ الإجراءات اللازمة بشأنه.","title":"دور دائرة الجمارك","memo":"⭐ دائرة الجمارك تحصل الضريبة عن السلع والخدمات المستوردة وتوردها للخزينة\n⭐ المخالفات والجرائم التي تضبطها الجمارك تحال إلى الدائرة لاتخاذ الإجراءات","qs":[{"q":"تتولى تحصيل الضريبة العامة على المبيعات عن السلع والخدمات المستوردة وتوريدها للخزينة:","o":["دائرة الجمارك","دائرة ضريبة الدخل والمبيعات مباشرة","البنك المركزي","وزارة الصناعة والتجارة"],"a":0},{"q":"إذا ضبطت دائرة الجمارك مخالفة خلافاً لأحكام قانون الضريبة العامة على المبيعات، فإنها:","o":["تحيلها إلى الدائرة لاتخاذ الإجراءات اللازمة بشأنها","تحيلها مباشرة إلى محكمة الجمارك البدائية","تفرض الغرامة وتحصلها بنفسها","تحيلها إلى مجلس الوزراء"],"a":0}]},{"n":"75","chapter":"","notes":[],"source":"أ- يصدر مجلس الوزراء الأنظمة اللازمة لتنفيذ أحكام هذا القانون بما في ذلك تنظيم أصول المحاكمات المتبعة في القضايا الحقوقية المقامة وفق أحكام هذا القانون بما في ذلك الأحكام المتعلقة بدفع الرسوم ومواعيد الطعن وإجراءاته ومحتويات اللائحة ومن له حق رفع الدعوى وجميع الأحكام والإجراءات اللازمة للسير فيها.\nب-يصدر الوزير بتنسيب من المدير التعليمات التنفيذية اللازمة لتنفيذ أحكام هذا القانون.","title":"الأنظمة والتعليمات التنفيذية","memo":"⭐ مجلس الوزراء يصدر الأنظمة اللازمة بما فيها أصول المحاكمات في القضايا الحقوقية\n⭐ الوزير يصدر التعليمات التنفيذية بتنسيب من المدير","qs":[{"q":"تصدر التعليمات التنفيذية اللازمة لتنفيذ أحكام قانون الضريبة العامة على المبيعات عن:","o":["الوزير بتنسيب من المدير","المدير بتنسيب من الوزير","مجلس الوزراء بتنسيب من الوزير","مجلس الوزراء بتنسيب من المدير"],"a":0},{"q":"الجهة التي تصدر الأنظمة المتعلقة بتنظيم أصول المحاكمات المتبعة في القضايا الحقوقية المقامة وفق أحكام القانون هي:","o":["مجلس الوزراء","الوزير","المدير","المجلس القضائي"],"a":0}]},{"n":"76","chapter":"","notes":[],"source":"يلغى قانون الضريبة على الاستهلاك رقم ٣٤ لسنة ١٩٨٨.","title":"إلغاء قانون الضريبة على الاستهلاك","memo":"⭐ يلغى قانون الضريبة على الاستهلاك رقم ٣٤ لسنة ١٩٨٨","qs":[{"q":"القانون الذي ألغي بموجب قانون الضريبة العامة على المبيعات هو:","o":["قانون الضريبة على الاستهلاك رقم ٣٤ لسنة ١٩٨٨","قانون ضريبة الدخل رقم ٥٧ لسنة ١٩٨٥","قانون الضريبة الإضافية رقم ٢٨ لسنة ١٩٦٩","قانون الجمارك رقم ٢٠ لسنة ١٩٩٨"],"a":0}]},{"n":"77","chapter":"","notes":["ألغيت التشريعات التالية بموجب المادة (١١) من القانون المؤقت المعدل رقم ٢٩ لسنة ٢٠٠٩ اعتبارا من ٢٠١٠/١/١:"],"source":"رئيس الوزراء والوزراء مكلفون بتنفيذ أحكام هذا القانون.","title":"الجهة المكلفة بتنفيذ القانون","memo":"⭐ رئيس الوزراء والوزراء مكلفون بتنفيذ أحكام هذا القانون.","qs":[{"q":"الجهة المكلفة بتنفيذ أحكام قانون الضريبة العامة على المبيعات هي:","o":["رئيس الوزراء والوزراء","وزير المالية والمدير","مجلس الأمة","المدير وموظفو الدائرة"],"a":0}]}]};
